/* Generated from Game_Engineering_Program_Manifest.json; lesson routes open the expanded readers in Packages 02-11. */
window.COURSE_INDEX = {"title":"Computer Science and Computer Engineering for Games","editionDate":"2026-09-28","planningHours":{"minimum":4500,"maximum":7200,"includes_projects_and_one_thesis":true,"not_academic_credits":true},"volumes":[{"number":1,"title":"Foundations and Your First Game","level":"Beginner / early undergraduate","purpose":"Learn to reason about programs, run code, debug, test, use Git and complete a tiny game.","hours":{"minimum":220,"maximum":340},"checkpoint":{"id":"A","title":"a complete first game"},"reader":"Game_Engineering_Package_02/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_02/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_02/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_02/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_02/LAB_WORKBOOK.pdf"},{"label":"Checkpoint A brief","path":"Game_Engineering_Package_02/CAPSTONE_SPEC.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_02/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":1,"title":"Starting as an engineer","prerequisites":"None. Basic reading, arithmetic and the ability to save a file.","project":"Create a learning repository with a working motion program, an environment record, a prediction table and a one-page explanation of the input-to-display path.","lessons":[{"id":"01.1","title":"What a program actually does","outcome":"Explain state, instructions, input and output using a tiny game.","practical":"On paper, trace five commands: right 3, left 1, right 0, left 4, right 2, starting at x = 2. Draw boxes for input, simulation state and output. Save the trace. Pass: every state transition is explainable without running code.","reading":"R03: introductory functions/variables lecture; R15: Basics of Information.","quizQuestions":3,"anchor":"lesson-01.1"},{"id":"01.2","title":"Files, terminals and reproducible execution","outcome":"Run a saved Python program and distinguish a shell from an interpreter.","practical":"Follow START_HERE. Run the included program twice from the same folder; save the command and output in your journal. Intentionally misspell the filename, read the error, then repair it. Pass: you can explain which program produced the error.","reading":"R04: Using the Python Interpreter; installation links in START_HERE.","quizQuestions":3,"anchor":"lesson-01.2"},{"id":"01.3","title":"Trace before running","outcome":"Predict a program by following assignments in order.","practical":"Create three assignment sequences with at least four statements each. Predict their outputs, then check with Python. Include one swap attempt that fails because it overwrites a needed value. Pass: fix the swap and explain the lost information.","reading":"R03: Functions, Variables; R04: An Informal Introduction to Python.","quizQuestions":3,"anchor":"lesson-01.3"},{"id":"01.4","title":"Units, budgets and engineering notebooks","outcome":"Use units and simple arithmetic to check game calculations.","practical":"Calculate travel at 2, 6 and 10 units/second for 0.1 and 0.5 seconds. Calculate frame intervals for 30, 60 and 120 frames/second. Pass: show units at every step and identify which assumptions are chosen targets.","reading":"R03: Variables and arithmetic; R15: Performance Measures.","quizQuestions":3,"anchor":"lesson-01.4"}]},{"number":2,"title":"Values, decisions and repetition","prerequisites":"Module 01.","project":"Build a terminal-based resource-gathering simulation with bounded health, inventory and a fixed number of turns. Include invalid-input handling and a complete trace for a five-turn run.","lessons":[{"id":"02.1","title":"Types and expressions","outcome":"Choose integers, real-valued numbers, strings and booleans appropriately.","practical":"Write a resource-cost calculator that converts two text inputs to integers and reports total cost. Test zero, a positive count and malformed text. Pass: invalid input produces a useful message rather than an unexplained crash.","reading":"R03: Functions, Variables and Exceptions; R04: Numbers and Text.","quizQuestions":3,"anchor":"lesson-02.1"},{"id":"02.2","title":"Conditions and boundary cases","outcome":"Write decisions with complete and non-overlapping rules.","practical":"Implement a door requiring either a key or both level >= 5 and stamina >= 10. Enumerate all key/no-key cases around the two numeric boundaries. Pass: explain why each case succeeds or fails.","reading":"R03: Conditionals; R04: if Statements.","quizQuestions":3,"anchor":"lesson-02.2"},{"id":"02.3","title":"Loops and invariants","outcome":"Use repetition that terminates and preserves a stated property.","practical":"Simulate ten turns, collecting three units each turn and spending five only when affordable. Print a trace. Pass: exactly ten updates occur and the resource count is never negative. Add a test for zero turns.","reading":"R03: Loops; R04: for Statements and range.","quizQuestions":3,"anchor":"lesson-02.3"},{"id":"02.4","title":"Functions and contracts","outcome":"Separate a calculation from interaction and state its valid inputs.","practical":"Implement advance with a documented nonnegative finite dt contract. Test stationary motion, negative velocity, zero dt and invalid dt. Pass: the function returns a value and the caller controls printing.","reading":"R03: Functions and Unit Tests; R04: Defining Functions.","quizQuestions":3,"anchor":"lesson-02.4"}]},{"number":3,"title":"Organizing data and small programs","prerequisites":"Module 02.","project":"Build a data-driven turn simulator with functions, a list of entities, a validated configuration file and save/load round-trip tests.","lessons":[{"id":"03.1","title":"Sequences, dictionaries and identity","outcome":"Choose collections according to the operations the program needs.","practical":"Store five units with stable IDs, names and health. Look up a unit by ID and create a filtered list of living units. Pass: renaming a unit does not break lookup, and the original collection is unchanged by filtering.","reading":"R04: Data Structures; R03: Loops and dictionaries.","quizQuestions":3,"anchor":"lesson-03.1"},{"id":"03.2","title":"Decomposition, modules and interfaces","outcome":"Divide a small game into parts that can be tested independently.","practical":"Refactor the resource simulation into simulation.py and a separate command-line entry point. Pass: importing simulation.py does not start a game or prompt the user, and a test can call its logic directly.","reading":"R04: Modules; R03: Libraries and Unit Tests.","quizQuestions":3,"anchor":"lesson-03.2"},{"id":"03.3","title":"Files, serialization and validation","outcome":"Save structured data without assuming every file is trustworthy.","practical":"Create JSON save/load functions for a small state. Test a normal round trip, missing field, wrong type, unsupported version and truncated file. Pass: the original working save remains usable after a failed load.","reading":"R04: Input and Output, json documentation linked from the standard library.","quizQuestions":3,"anchor":"lesson-03.3"},{"id":"03.4","title":"Classes, composition and state machines","outcome":"Represent behavior without creating an unnecessary inheritance hierarchy.","practical":"Implement a three-state character controller with a transition table. Pass: test every allowed transition and at least three forbidden transitions. Explain why composition would help add inventory independently of movement.","reading":"R04: Classes; R03: Object-Oriented Programming.","quizQuestions":3,"anchor":"lesson-03.4"}]},{"number":4,"title":"Debugging, testing and collaboration","prerequisites":"Modules 01-03.","project":"Publish a local tagged release of the terminal simulation with tests, a reproducible bug report, a reviewed change and an evidence-based development journal. A remote public upload is not required.","lessons":[{"id":"04.1","title":"Debugging as an experiment","outcome":"Find a defect by narrowing evidence rather than making random edits.","practical":"Introduce a double-damage bug into a copy of the simulator. Write expected/actual behavior, reduce the reproduction and use a breakpoint or trace to identify the first incorrect update. Pass: fix it with a regression test.","reading":"R03: Exceptions and Unit Tests; R11: assertions and error-handling guidance.","quizQuestions":3,"anchor":"lesson-04.1"},{"id":"04.2","title":"Unit, integration and property tests","outcome":"Choose tests that challenge the contract instead of repeating the implementation.","practical":"Write at least twelve tests across motion, resource spending and save/load. Include one property-style loop over many small inputs. Pass: temporarily insert a known bug and demonstrate that a relevant test fails.","reading":"R03: Unit Tests; R04: unittest standard-library documentation.","quizQuestions":3,"anchor":"lesson-04.2"},{"id":"04.3","title":"Git, branches and recoverable changes","outcome":"Use small commits to preserve reasoning and collaborate safely.","practical":"Initialize the course repository, make three focused commits and implement one feature on a branch. Merge it and practice reverting an intentionally bad commit in a disposable copy. Pass: identify exactly what changed and why.","reading":"R05: Getting Started, Git Basics and Basic Branching and Merging.","quizQuestions":3,"anchor":"lesson-04.3"},{"id":"04.4","title":"Review, documentation and responsible AI help","outcome":"Explain a change and verify assistance without surrendering understanding.","practical":"Review a ten-line change using a checklist: requirement, correctness, boundary cases, readability and tests. Write a README that a second person can follow. Pass: explain every changed line and recreate a small related feature without assistance.","reading":"R05: Distributed Git; R11: philosophy and interface guidance; course assessment policy.","quizQuestions":3,"anchor":"lesson-04.4"}]},{"number":5,"title":"A complete first game","prerequisites":"Modules 01-04.","project":"Complete Gate A: a deterministic terminal grid game with movement, obstacles, win/loss states, replay, tests and a clean-start README. Use the detailed project brief in the program handbook.","lessons":[{"id":"05.1","title":"The update loop and command model","outcome":"Separate simulation ticks from input collection and presentation.","practical":"Build a 10-by-10 terminal grid with one player and an exit. Pass: one command causes one update, drawing twice changes nothing, and the update function works without printing.","reading":"R20: runtime systems course overview; R27: fixed-step concepts, read without copying its implementation.","quizQuestions":3,"anchor":"lesson-05.1"},{"id":"05.2","title":"Collision rules and complete behavior","outcome":"Specify edge cases before implementing a playable rule.","practical":"Add five obstacles, a goal and a terminal win state. Test every edge of the board, blocked movement, reaching the goal and commands after victory. Pass: no partial movement occurs on rejected commands.","reading":"R20: game-programming projects; course transition and testing lessons.","quizQuestions":3,"anchor":"lesson-05.2"},{"id":"05.3","title":"Deterministic replay and simple measurement","outcome":"Reproduce a run and measure the work actually performed.","practical":"Save and replay a twenty-command session. Run the same replay repeatedly and compare final states. Time 10,000 headless updates separately from display. Pass: report exact inputs and no invented performance target.","reading":"R27: reproducibility motivation; R04: time and random standard-library references.","quizQuestions":3,"anchor":"lesson-05.3"},{"id":"05.4","title":"Finishing, usability and the first portfolio artifact","outcome":"Deliver a tiny game another person can run and understand.","practical":"Complete Gate A and ask a tester to start from the README without verbal help. Record three observations and fix at least one usability issue. Pass: the tester can start, play, quit and rerun the tests.","reading":"R29: Input, UI navigation and error-message guidelines; R05: tagging releases.","quizQuestions":3,"anchor":"lesson-05.4"}]}],"lessonCount":20},{"number":2,"title":"Mathematics for Games and Computing","level":"Undergraduate mathematical core","purpose":"Build the mathematical language for algorithms, graphics, physics, signals and experiments.","hours":{"minimum":500,"maximum":800},"checkpoint":{"id":"B","title":"a game-mathematics notebook"},"reader":"Game_Engineering_Package_03/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_03/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_03/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_03/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_03/LAB_WORKBOOK.pdf"},{"label":"Checkpoint B brief","path":"Game_Engineering_Package_03/CAPSTONE_SPEC.pdf"},{"label":"Math reference","path":"Game_Engineering_Package_03/MATH_REFERENCE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_03/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":6,"title":"Discrete mathematical reasoning","prerequisites":"Volume 01; complete the algebra diagnostic in START_HERE before proceeding.","project":"Write a mathematical notebook containing a truth-table specification, an induction proof, a graph model and a justified operation-count estimate. Include counterexamples to three false claims.","lessons":[{"id":"06.1","title":"Algebra, functions, logarithms and trigonometry","outcome":"Translate a game relationship into an equation with a defined domain.","practical":"Solve distance = speed*time for each variable and state forbidden inputs. Convert 0, 90, 180 and 360 degrees to radians. Pass: solve ten algebra problems and explain logarithms using repeated halving before advancing.","reading":"R08: prerequisite algebra review and trigonometric functions; R06: sums and asymptotics.","quizQuestions":3,"anchor":"lesson-06-1"},{"id":"06.2","title":"Logic, sets and quantified claims","outcome":"Express requirements precisely enough to test or prove.","practical":"Formalize five requirements for the grid game using sets and quantifiers. Construct truth tables for a door-access rule. Pass: provide a counterexample or witness for each negated requirement.","reading":"R06: propositions, predicates, sets and relations.","quizQuestions":3,"anchor":"lesson-06-2"},{"id":"06.3","title":"Proofs, induction and invariants","outcome":"Justify a program property instead of testing only examples.","practical":"Prove the formula 1+...+n = n(n+1)/2 by induction. Then write an invariant for counting living units in a prefix of a list. Pass: show initialization, preservation and termination explicitly.","reading":"R06: induction, invariants and proof methods.","quizQuestions":3,"anchor":"lesson-06-3"},{"id":"06.4","title":"Counting, graphs and recurrences","outcome":"Model combinations and recursive work without brute-force guessing.","practical":"Build a dependency graph for game startup and identify an invalid cycle. Count loadout combinations with and without a restriction. Pass: explain the recurrence for halving a search range and distinguish depth from total work.","reading":"R06: counting, graphs, recurrences and asymptotic notation.","quizQuestions":3,"anchor":"lesson-06-4"}]},{"number":7,"title":"Linear algebra and game geometry","prerequisites":"Module 06.1; basic Python functions.","project":"Build a tested vector/matrix library for a two-dimensional scene, then demonstrate a three-dimensional camera transformation with written coordinate conventions.","lessons":[{"id":"07.1","title":"Vectors, dot products and projections","outcome":"Use vectors for direction, distance and component measurements.","practical":"Implement length, dot and safe normalization. Use dot products to determine whether a target is in front of a character. Pass: test zero vectors, perpendicular vectors and opposite directions.","reading":"R07: vectors and projections; R23: Geometry and Transformations / Vectors.","quizQuestions":3,"anchor":"lesson-07-1"},{"id":"07.2","title":"Matrices, bases and linear systems","outcome":"Understand a matrix as a transformation rather than a table to memorize.","practical":"Implement 2-by-2 multiplication and solve two small linear systems by elimination on paper. Pass: show a pair of transforms that do not commute and explain a singular example geometrically.","reading":"R07: matrix multiplication, elimination, inverses and vector spaces.","quizQuestions":3,"anchor":"lesson-07-2"},{"id":"07.3","title":"Homogeneous transforms, cameras and quaternions","outcome":"Compose a scene using explicit coordinate conventions.","practical":"Create a parented object and camera using documented conventions. Pass: test identity, inverse round trips within tolerance, a translated direction that remains unchanged, and a parent rotation that moves its child correctly.","reading":"R23: Coordinate Systems and Transformations; R19: geometric transformations.","quizQuestions":3,"anchor":"lesson-07-3"},{"id":"07.4","title":"Eigenvalues, least squares and singular values","outcome":"Recognize stability and approximation problems in game data.","practical":"Fit a line to five noisy position/time observations and report residuals. Analyze repeated multiplication by a diagonal matrix. Pass: distinguish data noise, poor conditioning and a programming error in your report.","reading":"R07: eigenvalues, least squares and singular value decomposition.","quizQuestions":3,"anchor":"lesson-07-4"}]},{"number":8,"title":"Calculus, mechanics and numerical simulation","prerequisites":"Modules 06.1 and 07.1; work through the linked calculus problem sets.","project":"Build a projectile and spring simulator with analytic comparison cases, timestep refinement, unit checks and a report separating model error from numerical error.","lessons":[{"id":"08.1","title":"Limits, derivatives and rates","outcome":"Connect derivatives to velocity, acceleration and local approximation.","practical":"Compare analytic and finite-difference derivatives of three functions over several step sizes. Pass: include units, an error table and an explanation of why the smallest tested h need not be best.","reading":"R08: differentiation, product rule and chain rule.","quizQuestions":3,"anchor":"lesson-08-1"},{"id":"08.2","title":"Integrals, accumulation and continuous probability","outcome":"Interpret integration as accumulated contribution.","practical":"Implement rectangle and trapezoid integration for v(t)=2*t and a curved function. Pass: compare to an analytic integral, halve the step and report how error changes.","reading":"R08: integration and the fundamental theorem; R23: Monte Carlo Integration introduction.","quizQuestions":3,"anchor":"lesson-08-2"},{"id":"08.3","title":"Newtonian mechanics and differential equations","outcome":"Model motion from forces with clear simplifying assumptions.","practical":"Implement a particle under constant acceleration and a damped spring. Pass: compare the constant-acceleration trajectory to its analytic solution and state what collision, rotation and air-resistance effects are omitted.","reading":"R28: simulation, bodies, forces and impulses; R08: differential-equation applications.","quizQuestions":3,"anchor":"lesson-08-3"},{"id":"08.4","title":"Time integration, stability and error","outcome":"Choose and test a numerical update rather than assuming smaller code is correct.","practical":"Compare explicit and semi-implicit Euler on an undamped spring at three timesteps. Pass: plot or tabulate position and energy error, identify an unstable case, and avoid calling visual smoothness proof of physical accuracy.","reading":"R23: physically based animation topics via R19; R28: simulation stepping guidance.","quizQuestions":3,"anchor":"lesson-08-4"}]},{"number":9,"title":"Probability, statistics and evidence","prerequisites":"Modules 06 and 08.2.","project":"Create a reproducible benchmark experiment and a loot-distribution simulation. Report assumptions, uncertainty, representative workloads and one result that did not support the original hypothesis.","lessons":[{"id":"09.1","title":"Probability and conditional reasoning","outcome":"Model uncertainty without confusing independent and conditional events.","practical":"Simulate independent and dependent binary events. Build a small contingency table for a hypothetical bug detector. Pass: calculate both P(alert|bug) and P(bug|alert) and explain why they differ.","reading":"R09: probability, conditional probability and Bayes' theorem.","quizQuestions":3,"anchor":"lesson-09-1"},{"id":"09.2","title":"Random variables, distributions and sampling","outcome":"Distinguish an expected value from a guaranteed outcome.","practical":"Implement a weighted reward sampler and compare observed frequencies to the intended distribution over several sample sizes. Pass: record seed, generator, counts and expected values; explain finite-sample variation.","reading":"R09: random variables, expectation and variance; R04: random reference.","quizQuestions":3,"anchor":"lesson-09-2"},{"id":"09.3","title":"Inference, uncertainty and benchmark design","outcome":"Compare implementations without hiding variance or bias.","practical":"Compare two implementations using the same inputs, randomized test order and repeated runs. Pass: report median, a tail percentile, sample count and limitations; distinguish observations from causal claims.","reading":"R09: confidence intervals, hypothesis testing and experimental reasoning.","quizQuestions":3,"anchor":"lesson-09-3"},{"id":"09.4","title":"Regression, correlation and ethical telemetry","outcome":"Fit a model while recognizing confounding and data limits.","practical":"Fit a simple performance model using entity count and measured update time. Hold out some workloads. Pass: report prediction error and one confounder; write a short data-minimization plan for the experiment.","reading":"R09: regression and inference; R01: ethics and data-management breadth.","quizQuestions":3,"anchor":"lesson-09-4"}]},{"number":10,"title":"Signals, optimization and numerical foundations","prerequisites":"Modules 07-09.","project":"Complete Gate B: a mathematical engineering notebook plus tested transforms, numerical integration, signal filtering and an uncertainty-aware experiment.","lessons":[{"id":"10.1","title":"Multivariable calculus and gradients","outcome":"Use partial derivatives to reason about spatial fields and optimization.","practical":"Derive gradients for three functions and check them with centered differences. Pass: test nonzero and stationary points, vary perturbation size and report errors rather than claiming exact equality.","reading":"R07: linearization foundations; R23: geometric differential quantities; use the program's multivariable extension reading.","quizQuestions":3,"anchor":"lesson-10-1"},{"id":"10.2","title":"Sampling, aliasing and Fourier ideas","outcome":"Explain why discrete samples can misrepresent a continuous signal.","practical":"Generate low- and high-frequency sine samples, then downsample a checker pattern with and without prefiltering. Pass: explain the artifacts using frequency content rather than calling them random noise.","reading":"R10: sampling and Fourier representation; R23: Sampling and Reconstruction.","quizQuestions":3,"anchor":"lesson-10-2"},{"id":"10.3","title":"Convolution, filters and systems","outcome":"Predict a filter's effect on data and latency.","practical":"Implement a one-dimensional convolution with documented boundary handling. Test an impulse, a constant and a step. Pass: predict the output before running and identify the filter's delay convention.","reading":"R10: convolution, impulse response and linear time-invariant systems.","quizQuestions":3,"anchor":"lesson-10-3"},{"id":"10.4","title":"Optimization, conditioning and approximation budgets","outcome":"Choose an objective and distinguish convergence from correctness.","practical":"Implement gradient descent on a quadratic and a two-variable problem. Pass: compare step sizes, record residuals and state a stopping rule; complete Gate B with no unsupported claim of global optimality.","reading":"R07: least squares and conditioning; R23: numerical utilities; graduate optimization reading in the handbook.","quizQuestions":3,"anchor":"lesson-10-4"}]}],"lessonCount":20},{"number":3,"title":"C++, Algorithms and Language Implementation","level":"Undergraduate CS core","purpose":"Write native software safely, select data structures, analyze algorithms and build a tiny language.","hours":{"minimum":400,"maximum":650},"checkpoint":{"id":"C","title":"native simulation and a tiny language"},"reader":"Game_Engineering_Package_04/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_04/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_04/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_04/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_04/LAB_WORKBOOK.pdf"},{"label":"Checkpoint C brief","path":"Game_Engineering_Package_04/CAPSTONE_SPEC.pdf"},{"label":"C++ reference","path":"Game_Engineering_Package_04/CPP_REFERENCE.pdf"},{"label":"C language bridge","path":"Game_Engineering_Package_04/C_BRIDGE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_04/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":11,"title":"Native programming with C++","prerequisites":"Volume 01, Modules 06-07; do not skip the ownership module that follows.","project":"Port the deterministic grid simulation to C++20, with a command-line build, automated tests, warnings enabled and an explicit account of representation differences from Python.","lessons":[{"id":"11.1","title":"Compilation, linking and build systems","outcome":"Explain how source code becomes a runnable native program.","practical":"Build the included C++ starter, then split one function into a header and source file. Pass: reproduce and explain one compile error and one link error, then restore a warning-clean build.","reading":"R12: Getting Started and libraries; R11: Source Files.","quizQuestions":3,"anchor":"lesson-11-1"},{"id":"11.2","title":"Integer, floating-point and object representations","outcome":"Choose native types with explicit range and precision assumptions.","practical":"Print relevant sizes and numeric limits on the available compiler. Write checked conversions for a file length and tests for boundary values. Pass: do not trigger signed overflow as a test oracle; reject out-of-range input before converting.","reading":"R11: arithmetic and conversion guidance; R15: information encoding and arithmetic.","quizQuestions":3,"anchor":"lesson-11-2"},{"id":"11.3","title":"Values, references, pointers and lifetimes","outcome":"Track where an object lives and how long access remains valid.","practical":"Implement functions taking values, const references and pointers with a documented null policy. Pass: explain each lifetime and identify a deliberately supplied dangling-reference example without executing undefined behavior.","reading":"R11: Interfaces, Resource Management and lifetime safety guidance.","quizQuestions":3,"anchor":"lesson-11-3"},{"id":"11.4","title":"Standard containers, iterators and error handling","outcome":"Use library abstractions while respecting invalidation and failure contracts.","practical":"Port the unit list to std::vector and implement lookup with an explicit not-found result. Pass: test empty input, missing ID and growth; document which operations invalidate stored references.","reading":"R11: standard-library use and error handling; R12: testing integration.","quizQuestions":3,"anchor":"lesson-11-4"}]},{"number":12,"title":"Ownership, abstractions and C++ design","prerequisites":"Module 11.","project":"Build a small resource manager with explicit ownership, safe move behavior, bounded interfaces, fault-injection tests and a written comparison of composition and inheritance.","lessons":[{"id":"12.1","title":"RAII and resource ownership","outcome":"Make cleanup follow object lifetime on success and failure paths.","practical":"Wrap a mock file/device resource whose open/close counters can be inspected. Inject failure after acquisition. Pass: each acquired resource is released exactly once and no view outlives its owner.","reading":"R11: Resource Management and smart-pointer ownership rules.","quizQuestions":3,"anchor":"lesson-12-1"},{"id":"12.2","title":"Copy, move and exception safety","outcome":"Define what transferring a resource means without duplicating ownership.","practical":"Implement a move-only mock resource and transactional asset replacement. Pass: copying is prohibited, moving does not double-release, and injected load failure preserves the old asset.","reading":"R11: class special members, rule of zero and exception safety.","quizQuestions":3,"anchor":"lesson-12-2"},{"id":"12.3","title":"Interfaces, composition and polymorphism","outcome":"Choose abstractions according to substitutability and measured cost.","practical":"Create interchangeable console and recording renderers behind one small interface. Pass: both satisfy the same contract, tests run without display output, and ownership/destructor behavior is explicit.","reading":"R11: Interfaces, Class Hierarchies and composition guidance.","quizQuestions":3,"anchor":"lesson-12-3"},{"id":"12.4","title":"Templates, concepts and data-oriented choices","outcome":"Use generic code without hiding costs or exploding complexity.","practical":"Write a constrained generic clamp or interpolation function and benchmark two simple entity layouts. Pass: test contracts, record compiler/build mode and explain why the result is workload-specific.","reading":"R11: Templates and Generic Programming; R15: memory hierarchy motivation.","quizQuestions":3,"anchor":"lesson-12-4"}]},{"number":13,"title":"Data structures and their costs","prerequisites":"Modules 06 and 11-12.","project":"Implement educational versions of a dynamic array, queue, hash table and heap, each with invariants and tests. Compare them to standard containers without replacing standard code in production merely for practice.","lessons":[{"id":"13.1","title":"Complexity, arrays and linked structures","outcome":"Predict asymptotic work while recognizing locality and constants.","practical":"Implement a growable integer buffer for study. Count copied elements under doubling and one-at-a-time growth. Pass: derive the growth behavior and separately measure elapsed time without equating it to the proof.","reading":"R13: arrays, cost models and asymptotic analysis; R06: sums.","quizQuestions":3,"anchor":"lesson-13-1"},{"id":"13.2","title":"Stacks, queues and ring buffers","outcome":"Match ordering semantics to the intended workflow.","practical":"Implement a bounded queue with explicit full/empty results and wraparound tests. Pass: preserve FIFO order through more than three times its capacity in operations and never read an uninitialized slot.","reading":"R13: elementary data structures; R16: later concurrency comparison.","quizQuestions":3,"anchor":"lesson-13-2"},{"id":"13.3","title":"Hash tables and collision policies","outcome":"Explain expected lookup behavior and its assumptions.","practical":"Implement chaining or open addressing with collision tests and resizing. Pass: deliberately force many collisions, test missing keys and verify that distinct equal-hash keys remain distinct.","reading":"R13: hashing and dictionary data structures.","quizQuestions":3,"anchor":"lesson-13-3"},{"id":"13.4","title":"Trees, heaps and priority queues","outcome":"Preserve structural invariants and choose the right query behavior.","practical":"Implement a binary min-heap with push/pop and randomized comparison to a sorted reference. Pass: validate the heap invariant after every operation and test duplicate priorities.","reading":"R13: binary search trees, balanced trees and heaps.","quizQuestions":3,"anchor":"lesson-13-4"}]},{"number":14,"title":"Algorithms for maps, simulation and tools","prerequisites":"Modules 06, 09 and 13.","project":"Build a pathfinding visualizer and asset-dependency planner. Provide correctness arguments, unreachable cases, complexity analysis and measured comparisons on multiple map families.","lessons":[{"id":"14.1","title":"Searching, sorting and algorithm selection","outcome":"Choose an algorithm from its preconditions and the data distribution.","practical":"Implement binary search with a documented interval convention and test empty, one-element, duplicate and missing cases. Compare two sorts on random and nearly sorted inputs. Pass: verify output order and element preservation.","reading":"R13: binary search, sorting and comparison models.","quizQuestions":3,"anchor":"lesson-14-1"},{"id":"14.2","title":"Graph traversal and dependency ordering","outcome":"Use graph algorithms with explicit edge semantics.","practical":"Implement BFS and topological sorting. Pass: recover a shortest unweighted path, report unreachable goals, reject a cyclic dependency graph and justify the O(V+E) traversal bound for adjacency lists.","reading":"R13: graph representations, BFS, DFS and topological sorting.","quizQuestions":3,"anchor":"lesson-14-2"},{"id":"14.3","title":"Dijkstra, A* and admissible heuristics","outcome":"Build a correct pathfinder before optimizing its queue.","practical":"Implement Dijkstra and A* against the same grid model. Pass: compare path costs on many small maps, include no-path cases and demonstrate a deliberately overestimating heuristic that can sacrifice optimality.","reading":"R13: shortest paths; R20: game navigation context.","quizQuestions":3,"anchor":"lesson-14-3"},{"id":"14.4","title":"Dynamic programming, complexity limits and approximation","outcome":"Recognize repeated subproblems and justify a practical solution.","practical":"Solve a small 0/1 knapsack instance by exhaustive search and dynamic programming. Pass: compare answers, derive state count, and describe how a heuristic would be evaluated without claiming a guarantee it lacks.","reading":"R13: dynamic programming; R06: reductions and asymptotic reasoning.","quizQuestions":3,"anchor":"lesson-14-4"}]},{"number":15,"title":"Programming languages, compilers and computability","prerequisites":"Modules 11-14 and discrete proofs.","project":"Complete Gate C: a tested C++ simulation plus a tiny expression language with lexer, parser, evaluator, bytecode execution and resource limits.","lessons":[{"id":"15.1","title":"Language paradigms and type systems","outcome":"Separate language semantics from syntax and implementation habits.","practical":"Write one rule in imperative and pure-functional styles, then define a small typed C-compatible interface for a mock subsystem. Pass: state allocation ownership and reject type-invalid expressions in a toy checker.","reading":"R14: language frontend concepts; R11: interfaces and C-style boundary guidance.","quizQuestions":3,"anchor":"lesson-15-1"},{"id":"15.2","title":"Lexing, parsing and syntax trees","outcome":"Convert source text into a structured representation with diagnostics.","practical":"Implement tokens, recursive-descent parsing and evaluation for numbers, parentheses and four arithmetic operators. Pass: test precedence, associativity, malformed input, unknown names and division-by-zero policy.","reading":"R14: Kaleidoscope lexer, parser and abstract syntax tree chapters.","quizQuestions":3,"anchor":"lesson-15-2"},{"id":"15.3","title":"Bytecode, virtual machines and bounded execution","outcome":"Implement a small execution model with explicit limits.","practical":"Compile the expression language into stack bytecode and compare results to the tree evaluator. Pass: reject stack underflow, invalid opcodes and over-budget execution; preserve source context for errors.","reading":"R14: code generation and execution concepts; course security requirements.","quizQuestions":3,"anchor":"lesson-15-3"},{"id":"15.4","title":"Automata, computability and compiler optimization","outcome":"Know what analysis can establish and when transformation is legal.","practical":"Add constant folding to the toy compiler and test it against the unoptimized evaluator. Pass: include a finite-state recognizer, explain a termination restriction and document transformations deliberately excluded for semantic reasons.","reading":"R14: optimizer support; R06: computation models and proof limitations.","quizQuestions":3,"anchor":"lesson-15-4"}]}],"lessonCount":20},{"number":4,"title":"Computer Systems and Software Engineering","level":"Intermediate undergraduate","purpose":"Connect programs to processors, operating systems, concurrency, networks, storage and professional practice.","hours":{"minimum":380,"maximum":600},"checkpoint":{"id":"D","title":"a defensible systems application"},"reader":"Game_Engineering_Package_05/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_05/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_05/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_05/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_05/LAB_WORKBOOK.pdf"},{"label":"Checkpoint D brief","path":"Game_Engineering_Package_05/CAPSTONE_SPEC.pdf"},{"label":"Systems reference","path":"Game_Engineering_Package_05/SYSTEMS_REFERENCE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_05/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":16,"title":"Processor architecture and assembly","prerequisites":"Modules 11-15.","project":"Trace a compiled C++ loop through a small assembly example and a cache model. Deliver an instruction/data-flow explanation and a controlled locality experiment.","lessons":[{"id":"16.1","title":"Instruction sets, registers and calling conventions","outcome":"Read a small machine-level routine without confusing ISA and implementation.","practical":"Annotate a ten-to-twenty-instruction routine with register meanings and memory accesses. Pass: predict its output for two inputs and identify caller/callee responsibilities from the chosen ABI reference.","reading":"R15: Assembly Language and Procedures and Stacks; R35: selected base integer ISA.","quizQuestions":3,"anchor":"lesson-16-1"},{"id":"16.2","title":"Pipelines, dependencies and branch prediction","outcome":"Explain why instruction count alone does not predict latency.","practical":"Compare dependent and independent arithmetic loops while preventing dead-code elimination. Pass: preserve observable results, inspect generated code and explain measured differences as evidence rather than universal CPU facts.","reading":"R15: Pipelining and Performance Measures.","quizQuestions":3,"anchor":"lesson-16-2"},{"id":"16.3","title":"Caches, locality and memory hierarchy","outcome":"Relate access patterns to cache lines and working sets.","practical":"Benchmark sequential, strided and randomized access over multiple array sizes. Pass: record assumed versus measured hardware information and explain spatial locality without claiming exact cache behavior from one timing curve.","reading":"R15: Caches and the Memory Hierarchy.","quizQuestions":3,"anchor":"lesson-16-3"},{"id":"16.4","title":"Virtual memory, SIMD and architectural limits","outcome":"Recognize address translation and vector execution as separate mechanisms.","practical":"Inspect compiler vectorization reports for a simple loop and compare aligned/misaligned or tail cases safely. Pass: test lengths 0, 1, lane_width-1 and lane_width+1 and explain translation versus caching.","reading":"R15: Virtual Memory and Parallel Processing; R11: bounds and arithmetic contracts.","quizQuestions":3,"anchor":"lesson-16-4"}]},{"number":17,"title":"Operating systems and resource management","prerequisites":"Module 16.","project":"Create a systems lab report covering processes, memory, scheduling and file I/O. Use unprivileged programs and disposable data; do not alter kernel or device settings on a primary machine.","lessons":[{"id":"17.1","title":"Processes, threads, system calls and protection","outcome":"Explain which resources are isolated and which are shared.","practical":"Write a program that reports its process identity and runs independent worker tasks. Pass: explain what memory is shared in the chosen approach and how worker failure is reported without privileged operations.","reading":"R16: Processes, Process API and Threads.","quizQuestions":3,"anchor":"lesson-17-1"},{"id":"17.2","title":"Allocation, paging and memory-mapped data","outcome":"Distinguish reserved address space, committed storage and live objects.","practical":"Compare sequential file reads with a read-only mapped-file approach on a small disposable file. Pass: verify identical content and report virtual/resident concepts separately without promising one method is faster.","reading":"R16: Address Spaces, Address Translation, Paging and Memory API.","quizQuestions":3,"anchor":"lesson-17-2"},{"id":"17.3","title":"Scheduling, responsiveness and real-time constraints","outcome":"Distinguish average completion from meeting a deadline.","practical":"Simulate a scheduler or instrument a bounded producer/consumer workload without changing privileged priorities. Pass: show one contention-induced latency spike and propose a structural fix rather than only raising priority.","reading":"R16: Scheduling, Multi-Level Feedback Queue and Concurrency Bugs.","quizQuestions":3,"anchor":"lesson-17-3"},{"id":"17.4","title":"Filesystems, persistence and asynchronous I/O","outcome":"Design data operations that survive partial failure.","practical":"Build a save pipeline with injected failures before, during and after serialization. Pass: recover a valid prior or new save under your documented model and never reuse an asynchronous buffer before completion.","reading":"R16: Files and Directories, Crash Consistency and Journaling.","quizQuestions":3,"anchor":"lesson-17-4"}]},{"number":18,"title":"Concurrency and parallel programming","prerequisites":"Modules 12 and 16-17.","project":"Implement a bounded job system with dependency handling, shutdown, failure propagation and stress tests. Compare one-thread and multi-thread execution on a real workload.","lessons":[{"id":"18.1","title":"Races, mutexes and happens-before","outcome":"Protect shared invariants using a clear synchronization model.","practical":"Implement a shared counter and a compound inventory transaction with proper synchronization. Pass: stress test, inspect with an available race detector and explain why detector silence alone is not proof.","reading":"R11: Concurrency and Parallelism; R16: Locks and Concurrency Bugs.","quizQuestions":3,"anchor":"lesson-18-1"},{"id":"18.2","title":"Condition variables, deadlocks and cancellation","outcome":"Make waiting and shutdown correct under adverse timing.","practical":"Create a producer/consumer queue with graceful shutdown and failure propagation. Pass: test stopping with an empty queue, a full queue and active consumers; no thread remains blocked indefinitely.","reading":"R16: Condition Variables, Semaphores and Concurrency Bugs; R11: locking guidance.","quizQuestions":3,"anchor":"lesson-18-2"},{"id":"18.3","title":"Atomics, memory ordering and false sharing","outcome":"Use low-level synchronization only with a complete correctness argument.","practical":"Write a publication litmus test with a documented happens-before diagram. Measure a padded versus unpadded counter layout. Pass: do not claim stress tests prove memory-model correctness or assume a fixed cache-line size without labeling it.","reading":"R11: atomics and memory model; R16: concurrency; R37: later GPU memory-model comparison.","quizQuestions":3,"anchor":"lesson-18-3"},{"id":"18.4","title":"Task graphs, work stealing and scaling limits","outcome":"Parallelize independent work and measure end-to-end benefit.","practical":"Implement a small task graph for independent entity updates followed by aggregation. Pass: compare 1, 2 and available worker counts, verify results and explain a case where more workers hurt.","reading":"R15: Parallel Processing; R16: concurrency; R11: task-oriented concurrency guidance.","quizQuestions":3,"anchor":"lesson-18-4"}]},{"number":19,"title":"Networks, storage and data services","prerequisites":"Modules 15 and 17-18.","project":"Build a local-only client/server message exercise and a small relational game-data service. Test malformed framing, transaction rollback and duplicate requests without exposing a public service.","lessons":[{"id":"19.1","title":"Network layers, latency and transport semantics","outcome":"Choose transport behavior from application requirements.","practical":"Create a localhost client/server exchange with a length-prefixed message. Pass: split one message across several writes and combine several messages in one write; the receiver reconstructs them correctly.","reading":"R17: TCP service and interface semantics; R16: networking context.","quizQuestions":3,"anchor":"lesson-19-1"},{"id":"19.2","title":"Protocol design, serialization and timeouts","outcome":"Treat every received byte as untrusted structured input.","practical":"Add versioned framing, maximum sizes, timeout handling and request IDs to the lab protocol. Pass: reject oversized and truncated messages before dangerous allocation and test duplicate delivery.","reading":"R17: transport failure context; R18: transaction and data-integrity foundations.","quizQuestions":3,"anchor":"lesson-19-2"},{"id":"19.3","title":"Relational modeling, SQL and indexes","outcome":"Represent game data with constraints that survive application mistakes.","practical":"Create a small schema with primary, foreign and uniqueness constraints. Use parameterized queries and inspect one indexed query plan. Pass: demonstrate rejected invalid references and compare a query before/after indexing.","reading":"R18: tables, queries, joins, foreign keys and indexes via the linked manual.","quizQuestions":3,"anchor":"lesson-19-3"},{"id":"19.4","title":"Transactions, consistency and distributed failure","outcome":"Preserve invariants when several operations must succeed together.","practical":"Implement an inventory transfer with transactions and forced failure between updates. Pass: verify conservation, rollback and duplicate-request handling; document what is not guaranteed across processes or services.","reading":"R18: Transactions; R16: persistence and failure reasoning.","quizQuestions":3,"anchor":"lesson-19-4"}]},{"number":20,"title":"Engineering practice, security and maintainability","prerequisites":"Volumes 01-04.","project":"Complete Gate D: a reviewed systems application with a design record, threat model, CI-style local test pipeline, dependency inventory and an incident/recovery exercise.","lessons":[{"id":"20.1","title":"Requirements, architecture and design records","outcome":"Make tradeoffs explicit and trace implementation back to needs.","practical":"Write six measurable requirements and two decision records for the simulation. Pass: every requirement has an acceptance test and each decision includes a rejected alternative and a cost.","reading":"R01: Software Engineering; R02: engineering design and professional practice.","quizQuestions":3,"anchor":"lesson-20-1"},{"id":"20.2","title":"Defensive programming and threat modeling","outcome":"Protect assets and trust boundaries before selecting security mechanisms.","practical":"Threat-model the save parser and local service. Add bounds checks and a small malformed-input fuzz harness. Pass: cap work/memory, preserve useful errors and record residual risks instead of claiming complete security.","reading":"R01: Security; R11: bounds/lifetime safety; R02: information-security breadth.","quizQuestions":3,"anchor":"lesson-20-2"},{"id":"20.3","title":"Build automation, dependencies and release discipline","outcome":"Produce a verifiable artifact from a known source revision.","practical":"Create a local clean-build script that runs tests and produces a versioned archive plus manifest. Pass: run it from a fresh build directory and deliberately break a test to confirm the pipeline stops.","reading":"R05: workflows and tagging; R12: builds and testing; R01: software engineering.","quizQuestions":3,"anchor":"lesson-20-3"},{"id":"20.4","title":"Ethics, accessibility, teamwork and sustainable delivery","outcome":"Evaluate engineering decisions beyond code correctness.","practical":"Run an accessibility review and a blameless failure retrospective on the project. Pass: identify at least three actionable changes, assign acceptance evidence and document third-party attribution honestly.","reading":"R29: input, text, captions and UI guidance; R01/R02: professional and ethical practice.","quizQuestions":3,"anchor":"lesson-20-4"}]}],"lessonCount":20},{"number":5,"title":"Graphics and Game-Engine Construction","level":"Upper undergraduate","purpose":"Build a renderer and a small engine instead of only learning an existing editor.","hours":{"minimum":420,"maximum":650},"checkpoint":{"id":"E","title":"a small 3D engine"},"reader":"Game_Engineering_Package_06/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_06/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_06/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_06/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_06/LAB_WORKBOOK.pdf"},{"label":"Checkpoint E brief","path":"Game_Engineering_Package_06/CAPSTONE_SPEC.pdf"},{"label":"Engine reference","path":"Game_Engineering_Package_06/ENGINE_REFERENCE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_06/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":21,"title":"From geometry to a software renderer","prerequisites":"Modules 07-08, 11-16; complete the mathematics checkpoint.","project":"Build a CPU renderer that writes a portable image file. It must clip geometry, rasterize triangles, resolve visibility and interpolate attributes correctly. Keep it as a reference implementation for future GPU work.","lessons":[{"id":"21.1","title":"Images, color and coordinate conventions","outcome":"Define the numerical and geometric meaning of an image buffer.","practical":"Write a PPM image containing a gradient and coordinate markers. Pass: the dimensions, orientation and channel values are verified by tests, and a README states all coordinate and color assumptions.","reading":"R19: image representation and transformations; R23: Radiometry, Spectra, and Color.","quizQuestions":3,"anchor":"lesson-21.1"},{"id":"21.2","title":"Projection and clipping before perspective division","outcome":"Transform geometry without confusing visibility with division by depth.","practical":"Implement clipping against one plane, then the complete chosen clip volume. Pass: triangles crossing the near plane remain finite and correctly shaped, and tests cover points exactly on the boundary.","reading":"R19: perspective transformations, clipping and the graphics pipeline; R23: Cameras.","quizQuestions":3,"anchor":"lesson-21.2"},{"id":"21.3","title":"Triangle coverage, depth and perspective-correct interpolation","outcome":"Produce crack-resistant filled triangles with correct varying attributes.","practical":"Render two triangles sharing an edge and a receding checkerboard. Pass: no cracks under the documented fill rule, correct overlap ordering, and a visible comparison between affine and perspective-correct texture coordinates.","reading":"R19: rasterization, barycentric coordinates and texture mapping; R23: Sampling and Reconstruction.","quizQuestions":3,"anchor":"lesson-21.3"},{"id":"21.4","title":"Rays, intersections and acceleration structures","outcome":"Build a second visibility method and compare its costs with rasterization.","practical":"Implement sphere or triangle intersections and a small BVH. Pass: accelerated and brute-force results agree within a defined tolerance over randomized rays, including misses and grazing cases; report build and query costs separately.","reading":"R23: Shapes and Primitives and Intersection Acceleration.","quizQuestions":3,"anchor":"lesson-21.4"}]},{"number":22,"title":"Explicit GPU programming and graphics APIs","prerequisites":"Module 21 plus Modules 18 and 20. Choose one compatible backend, not all at once.","project":"Implement a GPU backend for the reference scene. Query device capabilities, enable available validation, document the toolchain and handle resize and shutdown safely. A CPU backend remains a valid fallback while hardware access is arranged.","lessons":[{"id":"22.1","title":"GPU work submission, resources and pipeline state","outcome":"Separate CPU recording from asynchronous GPU execution.","practical":"Create a window or offscreen target and report supported capabilities. Pass: render a clear color, capture validation output and explain which objects belong to CPU recording versus GPU execution.","reading":"R21: Introduction and Drawing a Triangle; alternatively R24 or R25 for one native platform; R22: SDL3 platform setup.","quizQuestions":3,"anchor":"lesson-22.1"},{"id":"22.2","title":"Buffers, shaders, layouts and resource binding","outcome":"Match data representations across CPU and GPU boundaries.","practical":"Upload a transform and vertex colors, then add a bounded compute operation. Pass: host/shader layouts are documented, a readback test checks results, and non-multiple work sizes remain correct.","reading":"R21: vertex buffers, uniform buffers and compute; R37: execution configuration and memory organization, only for the optional CUDA route.","quizQuestions":3,"anchor":"lesson-22.2"},{"id":"22.3","title":"Synchronization, hazards and frames in flight","outcome":"Express dependencies without serializing the entire renderer.","practical":"Implement a compute-to-draw dependency and two reusable frame contexts. Pass: validation reports no relevant hazards and a stress test never resets a context still used by the GPU.","reading":"R21: synchronization, frames in flight and resource transitions; use R24 or R25 equivalents for the selected backend.","quizQuestions":3,"anchor":"lesson-22.3"},{"id":"22.4","title":"Presentation, resizing and device capability policy","outcome":"Treat the window system as a changing environment rather than a fixed image.","practical":"Stress resize, minimize, restore and orderly shutdown. Pass: no stale size-dependent resources, no division by zero, and a readable capability report explains enabled features and fallbacks.","reading":"R21: swapchain recreation and device selection; R22: window events; R24 or R25: presentation and resource lifetime.","quizQuestions":3,"anchor":"lesson-22.4"}]},{"number":23,"title":"Lighting, materials and real-time image quality","prerequisites":"Modules 07, 09-10, 21-22.","project":"Create a material-and-lighting demonstration with a documented color pipeline. Compare image quality and frame cost at identical resolution and scene content; include reference images, not only attractive screenshots.","lessons":[{"id":"23.1","title":"Radiometry, reflectance and physically based materials","outcome":"Explain how lighting models approximate light transport.","practical":"Implement diffuse lighting and one documented microfacet model. Pass: test a constant environment, grazing angles and roughness limits, and state approximations rather than labeling any shiny shader physically exact.","reading":"R23: Radiometry, Reflection Models and Light Transport; R19: shading.","quizQuestions":3,"anchor":"lesson-23.1"},{"id":"23.2","title":"Textures, mipmaps, filtering and tangent-space detail","outcome":"Control aliasing while preserving the meaning of texture data.","practical":"Render a receding textured floor with and without mipmaps and inspect a normal-mapped seam. Pass: report texture storage including mip levels and explain why non-color data needs its own filtering policy.","reading":"R23: Textures and Sampling and Reconstruction; R21: texture images, samplers and mipmaps.","quizQuestions":3,"anchor":"lesson-23.2"},{"id":"23.3","title":"Shadows, light selection and rendering-path tradeoffs","outcome":"Choose a lighting architecture from scene and bandwidth requirements.","practical":"Implement shadow mapping and compare a simple forward path with tiled light selection or a small deferred prototype. Pass: disclose buffer sizes, light counts, transparency limitations and measured frame costs.","reading":"R19: real-time rendering and shadows; R23: Lights and Light Transport.","quizQuestions":3,"anchor":"lesson-23.3"},{"id":"23.4","title":"HDR, tone mapping, temporal reconstruction and validation","outcome":"Separate display mapping from reconstruction and simulation correctness.","practical":"Add exposure, a documented tone mapper and a basic temporal accumulation experiment. Pass: capture a camera cut and disocclusion test, show failure modes, and compare both still-image error and motion behavior.","reading":"R23: Film and Imaging and Sampling; R19: anti-aliasing and image processing.","quizQuestions":3,"anchor":"lesson-23.4"}]},{"number":24,"title":"Engine architecture, simulation and resource ownership","prerequisites":"Modules 12, 17-18, 21-23.","project":"Build a small engine with a fixed-step world, generational entity handles, explicit resource ownership and an inspectable task graph. Keep the game rules separate enough to run automated headless tests.","lessons":[{"id":"24.1","title":"Fixed updates, interpolation and overload policy","outcome":"Separate simulation time from rendering time and real elapsed time.","practical":"Implement an accumulator loop and inject long frames. Pass: simulation advances consistently under normal load, interpolation is bounded, and the overload behavior is tested rather than silently spiraling.","reading":"R27: Fix Your Timestep!; R20: game loops and timing. Use the article as a starting model, not a guarantee of determinism.","quizQuestions":3,"anchor":"lesson-24.1"},{"id":"24.2","title":"Entities, components, handles and data-oriented storage","outcome":"Design identity separately from memory location.","practical":"Implement a small generational entity store with two components and deferred destruction. Pass: stale handles fail safely, iteration survives queued changes, and benchmarks include creation, deletion and common queries.","reading":"R20: game-state organization; R26: gameplay architecture for comparison; R11: lifetime and interface guidance.","quizQuestions":3,"anchor":"lesson-24.2"},{"id":"24.3","title":"Allocators, task graphs and frame-resource lifetime","outcome":"Make temporary storage and parallel dependencies observable.","practical":"Create a serial-then-parallel task graph and a checked temporary arena. Pass: resetting live storage is detected in tests, dependency order is verified, and the critical path is identified from a trace.","reading":"R11: ownership and concurrency; R20: engine architecture; R26: engine systems as a comparative implementation.","quizQuestions":3,"anchor":"lesson-24.3"},{"id":"24.4","title":"Subsystem boundaries, save formats and reloadability","outcome":"Choose interfaces that make change and failure manageable.","practical":"Add versioned saves and one reloadable asset type. Pass: old supported data migrates, malformed data is rejected without partial world corruption, and subsystem shutdown works after injected initialization failure.","reading":"R20: resource management and tools; R26: serialization and gameplay architecture; R11: interfaces and error handling.","quizQuestions":3,"anchor":"lesson-24.4"}]},{"number":25,"title":"Asset pipelines, editors and an integrated engine","prerequisites":"Module 24 and the software-engineering practices of Module 20.","project":"Gate E: deliver a small 3D engine demonstration with an asset cooker, reproducible scene, inspector, save/load, diagnostics and a measured frame/memory budget. A second person must build and run it from the README.","lessons":[{"id":"25.1","title":"Importing, cooking and content-addressed asset builds","outcome":"Treat assets as compiled inputs with dependency tracking.","practical":"Build a cooker for one mesh and one image representation. Pass: identical declared inputs reproduce the same result, changed settings invalidate the cache, and corrupted sources produce readable failures.","reading":"R20: asset pipelines; R26: asset management and content tools. Apply Module 20 dependency and provenance practices.","quizQuestions":3,"anchor":"lesson-25.1"},{"id":"25.2","title":"Streaming, residency and memory budgets","outcome":"Load content without allowing asynchronous work to violate ownership.","practical":"Implement a bounded streaming queue with placeholder assets and cancellation. Pass: a forced small budget produces graceful fallback, no use-after-free, and a report of peak rather than only steady-state memory.","reading":"R20: resource loading; R26: asset management, asynchronous loading and streaming concepts.","quizQuestions":3,"anchor":"lesson-25.2"},{"id":"25.3","title":"Editors, inspection and undoable commands","outcome":"Make engine state understandable and safely editable.","practical":"Create a scene inspector with transform editing and a ten-command undo/redo test. Pass: invalid inputs are rejected, focus does not trigger unintended gameplay, and save/reload preserves committed changes.","reading":"R20: game tools; R26: editor and reflection concepts. Use a minimal UI toolkit appropriate to the selected platform.","quizQuestions":3,"anchor":"lesson-25.3"},{"id":"25.4","title":"Engine integration and reproducible demonstration","outcome":"Deliver a small complete system whose limitations are measurable.","practical":"Complete Gate E using the project specification in the handbook. Pass: another person follows the README, a headless test scene passes, all assets have provenance, and a limitations section identifies remaining correctness or performance risks.","reading":"R20: project completion; R26: profiling and engine architecture comparison; revisit Module 20 release and review practices.","quizQuestions":3,"anchor":"lesson-25.4"}]}],"lessonCount":20},{"number":6,"title":"Game Systems and Production","level":"Upper undergraduate / engineering capstone","purpose":"Add simulation, animation, audio, AI, multiplayer, accessibility and release discipline.","hours":{"minimum":420,"maximum":650},"checkpoint":{"id":"F","title":"undergraduate software capstone"},"reader":"Game_Engineering_Package_07/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_07/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_07/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_07/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_07/LAB_WORKBOOK.pdf"},{"label":"Checkpoint F brief","path":"Game_Engineering_Package_07/CAPSTONE_SPEC.pdf"},{"label":"Systems reference","path":"Game_Engineering_Package_07/SYSTEMS_REFERENCE.pdf"},{"label":"Native integration guide","path":"Game_Engineering_Package_07/NATIVE_INTEGRATION_GUIDE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_07/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":26,"title":"Collision detection and physical simulation","prerequisites":"Modules 07-10, 14 and 24.","project":"Build a deterministic test harness for a small physics scene, compare your simple implementation with a maintained physics library, and record precisely which physical and numerical assumptions differ.","lessons":[{"id":"26.1","title":"Broad phase, narrow phase and geometric robustness","outcome":"Separate possible collisions from confirmed contacts.","practical":"Implement a grid broad phase and circle or box narrow phase. Pass: no true pairs are omitted compared with brute force over randomized scenes, and boundary-touching behavior is documented.","reading":"R28: collision module, shapes and broad-phase concepts; R19: geometry and collision.","quizQuestions":3,"anchor":"lesson-26.1"},{"id":"26.2","title":"Rigid bodies, angular motion and collision impulses","outcome":"Use conservation laws with explicit approximations.","practical":"Implement center-of-mass impulses and a simple rotational case. Pass: momentum is conserved in isolated tests within tolerance, static bodies remain fixed, and energy behavior matches the chosen restitution model.","reading":"R28: rigid bodies, contacts and simulation; R19: physical simulation.","quizQuestions":3,"anchor":"lesson-26.2"},{"id":"26.3","title":"Constraints, iterative solvers and continuous collision detection","outcome":"Explain where discrete simulation fails and how solvers control error.","practical":"Create a fast-projectile tunneling test and a short chain of constraints. Pass: a continuous or swept test catches the projectile, and a plot or table shows constraint error versus iteration count and timestep.","reading":"R28: joints, solver settings and continuous collision; R19: numerical simulation.","quizQuestions":3,"anchor":"lesson-26.3"},{"id":"26.4","title":"Physics testing, determinism and engine integration","outcome":"Validate simulation with invariants and adversarial scenes.","practical":"Build a regression suite with replay hashes on one pinned environment, finite-value checks and analytic tests. Pass: failures identify the first divergent tick and reports distinguish same-machine repeatability from cross-platform determinism.","reading":"R28: simulation, determinism and limitations; revisit Modules 08 and 24.","quizQuestions":3,"anchor":"lesson-26.4"}]},{"number":27,"title":"Animation, audio and interactive timing","prerequisites":"Modules 07, 10, 18 and 24.","project":"Integrate an animated character or articulated object with event-driven audio. Demonstrate smooth interpolation, bounded audio work, adjustable sound categories and correct behavior when animation rate differs from simulation rate.","lessons":[{"id":"27.1","title":"Skeletons, transforms and skinning","outcome":"Compute hierarchical animation without mixing coordinate spaces.","practical":"Animate a two-joint mesh or line skeleton. Pass: the bind pose reproduces the source geometry, weights are validated and a parent rotation moves descendants consistently.","reading":"R19: transformations and animation; R26: skeletal animation concepts.","quizQuestions":3,"anchor":"lesson-27.1"},{"id":"27.2","title":"Animation blending, state machines and inverse kinematics","outcome":"Coordinate authored motion with runtime goals.","practical":"Build idle/walk/action transitions and a two-link IK demonstration. Pass: interruptions behave as specified, unreachable targets are handled, and root-motion ownership is documented.","reading":"R19: animation and inverse kinematics; R26: animation blueprints and blending concepts, compared with your own small implementation.","quizQuestions":3,"anchor":"lesson-27.2"},{"id":"27.3","title":"Digital audio, mixing and real-time callback discipline","outcome":"Generate sound without missing the output deadline.","practical":"Mix two generated tones with adjustable gains using a platform audio API. Pass: no clipping under the documented gain policy, bounded callback work and a recorded underrun or deadline-stress test.","reading":"R10 from Volume 2: sampling and filtering; R22: SDL3 audio; R20: audio systems.","quizQuestions":3,"anchor":"lesson-27.3"},{"id":"27.4","title":"Spatial audio, animation events and multimodal accessibility","outcome":"Synchronize feedback while preserving user control.","practical":"Add spatial panning, separate music/effects controls and a visual equivalent for a critical audio cue. Pass: replay does not duplicate one-shot events and a muted-audio test still allows the required task.","reading":"R20: audio and event systems; R22: audio interfaces; R29 from the resource directory: audio and subtitle accessibility.","quizQuestions":3,"anchor":"lesson-27.4"}]},{"number":28,"title":"Game AI, decision systems and machine learning","prerequisites":"Modules 09, 14, 24 and 26.","project":"Build an inspectable agent that navigates, chooses actions and recovers from blocked plans. Compare a rules-based baseline with one small learned or search-based component; evaluate behavior and runtime cost, not only win rate.","lessons":[{"id":"28.1","title":"Navigation graphs, steering and dynamic obstacles","outcome":"Separate finding a route from executing movement.","practical":"Combine A* with a steering controller and a blocked-path detector. Pass: agent size is respected, unreachable goals terminate or report failure, and repeated replanning has a bounded budget.","reading":"R46: Search; R20: game AI and navigation concepts.","quizQuestions":3,"anchor":"lesson-28.1"},{"id":"28.2","title":"Behavior trees, utility systems and explainable decisions","outcome":"Represent behavior so designers can understand its failures.","practical":"Implement either a small behavior tree or utility selector with a trace viewer. Pass: action cancellation releases resources and three induced failure cases produce understandable explanations.","reading":"R20: game AI; R46: agents, utilities and decision-making foundations.","quizQuestions":3,"anchor":"lesson-28.2"},{"id":"28.3","title":"Adversarial search, planning and simulation budgets","outcome":"Trade decision quality against bounded computation.","practical":"Implement minimax with alpha-beta or a small MCTS agent for a tiny game. Pass: legal moves are always returned within a defined budget or fallback, and evaluation includes multiple seeds and opponents.","reading":"R46: Games, Minimax, Expectimax and Monte Carlo Tree Search.","quizQuestions":3,"anchor":"lesson-28.3"},{"id":"28.4","title":"Learning systems, neural inference and responsible evaluation","outcome":"Understand learning fundamentals without replacing every subsystem with a model.","practical":"Train a small classifier or value estimator on synthetic game data and compare it with a rules baseline. Pass: independent splits, error analysis, inference timing, reproducible seeds and a fallback behavior are reported.","reading":"R46: Machine Learning and Reinforcement Learning; R47: linear models, multilayer perceptrons, backpropagation and generalization.","quizQuestions":3,"anchor":"lesson-28.4"}]},{"number":29,"title":"Multiplayer simulation and online services","prerequisites":"Modules 18-20 and 24; Module 26 for physical interaction.","project":"Create a local two-client multiplayer demonstration with a network simulator for delay, jitter, loss, duplication and reordering. No public server or paid cloud account is required. Document authority and recovery rules.","lessons":[{"id":"29.1","title":"Authority, prediction and reconciliation","outcome":"Provide responsive local control without trusting arbitrary client outcomes.","practical":"Implement a one-dimensional or grid movement server with client prediction. Pass: invalid movement is rejected and induced delay produces documented corrections without permanently diverging state.","reading":"R17: transport semantics; R26: networking and multiplayer concepts; R20: networking in games.","quizQuestions":3,"anchor":"lesson-29.1"},{"id":"29.2","title":"Snapshots, interpolation, relevance and lag compensation","outcome":"Manage bandwidth and latency while making fairness assumptions explicit.","practical":"Add remote interpolation and relevance filtering. Pass: out-of-order snapshots are handled, missing baselines trigger recovery, and the report explains both visual delay and hidden-state exposure policy.","reading":"R20: networked game state; R26: replication and network smoothing; revisit Module 19 message validation.","quizQuestions":3,"anchor":"lesson-29.2"},{"id":"29.3","title":"Lockstep, rollback and deterministic replay","outcome":"Choose synchronization around the game model rather than genre slogans.","practical":"Implement rollback or input lockstep for the tiny deterministic game. Pass: a delayed-input test converges, state hashes detect a deliberately introduced divergence, and audio or reward side effects are not duplicated.","reading":"R20 and R26: multiplayer concepts; derive the implementation using Modules 18, 24 and 26 rather than assuming engine-specific guarantees.","quizQuestions":3,"anchor":"lesson-29.3"},{"id":"29.4","title":"Match services, identity, persistence and failure recovery","outcome":"Design a small online service without treating it as part of the render loop.","practical":"Build a local match registry and idempotent result store. Pass: duplicate submissions do not duplicate rewards, unauthorized edits fail, and simulated service loss produces a documented client outcome.","reading":"R18 from the directory: transactions; R17: transport; revisit Modules 19-20 for distributed failure and threat modeling.","quizQuestions":3,"anchor":"lesson-29.4"}]},{"number":30,"title":"Production quality and the undergraduate engine capstone","prerequisites":"Modules 21-29 plus Gate D software-engineering evidence.","project":"Gate F: release a small original game using your engine, with one complete gameplay loop, settings, save/load, diagnostics, accessibility checks, a tested distribution and a technical postmortem. Scope is judged by quality of evidence, not visual size.","lessons":[{"id":"30.1","title":"Profiling, frame budgets and performance regression tests","outcome":"Optimize measured bottlenecks without sacrificing correctness.","practical":"Profile the capstone scene, optimize one verified bottleneck and add a regression benchmark. Pass: repeated before/after results, unchanged correctness and disclosed measurement uncertainty are included.","reading":"R26: profiling and optimization; R45: sanitizer diagnostics; revisit Modules 09 and 18.","quizQuestions":3,"anchor":"lesson-30.1"},{"id":"30.2","title":"Compatibility, accessibility, localization and human testing","outcome":"Test whether people can actually use the complete product.","practical":"Test the game at two window sizes, with remapped input and an expanded pseudo-localized text set. Pass: no critical clipped controls, a muted-audio task remains solvable and observed usability issues are tracked.","reading":"R29: input, text, audio, contrast and UI guidelines; R20: playtesting and production.","quizQuestions":3,"anchor":"lesson-30.2"},{"id":"30.3","title":"Packaging, patching, modding and supply-chain boundaries","outcome":"Distribute a game without creating an uncontrolled execution path.","practical":"Package the game and implement a data-only mod with a versioned schema. Pass: a clean-folder launch works, oversized or malformed mods are rejected and an interrupted-update simulation preserves a valid version.","reading":"R20: production; R26: packaging and plugins; R45 and Module 20: defensive memory and dependency practices.","quizQuestions":3,"anchor":"lesson-30.3"},{"id":"30.4","title":"Capstone review, release and technical postmortem","outcome":"Demonstrate ownership of a complete engineering result.","practical":"Complete Gate F and the oral questions in the handbook. Pass: another tester finishes a full loop, the release is reproducible, critical defects are resolved or clearly blocked from release, and the postmortem cites measured evidence.","reading":"R20: course projects and critique; revisit the project rubric and professional-practice lessons.","quizQuestions":3,"anchor":"lesson-30.4"}]}],"lessonCount":20},{"number":7,"title":"Computer Engineering and Digital Design","level":"Undergraduate CE core","purpose":"Move from circuits and gates to RTL, a processor and an FPGA-based game subsystem.","hours":{"minimum":450,"maximum":720},"checkpoint":{"id":"G","title":"undergraduate digital-design capstone"},"reader":"Game_Engineering_Package_08/OPEN_COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_08/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_08/docs/START_HERE.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_08/docs/VOLUME_07_HANDBOOK.pdf"},{"label":"Lab and project workbook","path":"Game_Engineering_Package_08/docs/LAB_AND_PROJECT_WORKBOOK.pdf"},{"label":"Checkpoint G brief","path":"Game_Engineering_Package_08/docs/GATE_G_CAPSTONE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_08/docs/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":31,"title":"Circuits, measurement and electronic foundations","prerequisites":"Modules 06-10; basic algebra and calculus competence required. Simulation is the default laboratory.","project":"Create a circuit laboratory notebook using simulation first: voltage/current prediction, an RC transient, a transistor switch and a sampled input. Physical extensions require a qualified mentor and a documented low-voltage safety review.","lessons":[{"id":"31.1","title":"Voltage, current, resistance and safe measurement","outcome":"Analyze a simple circuit using units and conservation laws.","practical":"Simulate a two-resistor divider and verify node voltages and current conservation. Pass: predictions include units, the source/load assumptions are stated, and a safety checklist precedes any physical experiment.","reading":"R30: lumped-circuit abstraction, resistive networks and basic circuit analysis.","quizQuestions":3,"anchor":"lesson-31.1"},{"id":"31.2","title":"Capacitors, inductors, transients and frequency response","outcome":"Relate stored energy to timing and filtering behavior.","practical":"Simulate an RC step response and a sinusoidal frequency sweep. Pass: the measured time constant agrees with the ideal calculation within numerical tolerance, and the report distinguishes transient from steady-state behavior.","reading":"R30: capacitors, inductors, first- and second-order systems; R10: frequency response.","quizQuestions":3,"anchor":"lesson-31.2"},{"id":"31.3","title":"Diodes, transistors, CMOS and analog interfaces","outcome":"Understand the physical devices beneath digital abstractions.","practical":"Simulate a CMOS inverter and one simple amplifier or comparator stage. Pass: plot input/output behavior, identify valid operating regions and explain one failure of the idealized model.","reading":"R30: MOS transistors, amplifiers, digital circuits and operational amplifiers.","quizQuestions":3,"anchor":"lesson-31.3"},{"id":"31.4","title":"Sampling, ADCs, DACs and noisy controller inputs","outcome":"Convert physical signals into stable digital measurements.","practical":"Simulate a noisy joystick signal, quantization and a simple filter. Pass: report step size, calibration error, added response delay and behavior near the dead-zone boundary.","reading":"R30: mixed-signal and measurement concepts; R10: sampling and filtering.","quizQuestions":3,"anchor":"lesson-31.4"}]},{"number":32,"title":"Digital logic, state and timing","prerequisites":"Modules 06, 15-16 and 31.","project":"Build and test an arithmetic unit, a finite-state controller and a synchronous queue model. For every block, provide a truth table or transition specification before coding its implementation.","lessons":[{"id":"32.1","title":"Boolean logic and combinational building blocks","outcome":"Translate a logical specification into a circuit with no stored state.","practical":"Implement a small multiplexer, decoder and four-bit adder in a logic simulator or model. Pass: exhaustive truth-table tests cover every supported input and no state is required for a result.","reading":"R15: combinational logic; R31: Boolean logic and arithmetic projects.","quizQuestions":3,"anchor":"lesson-32.1"},{"id":"32.2","title":"Registers, finite-state machines and synchronous timing","outcome":"Model state transitions at clock boundaries.","practical":"Design a controller with idle, running and done states, including reset and abort. Pass: a transition table matches simulation and a timing worksheet includes setup and hold as different checks.","reading":"R15: sequential logic and finite-state machines; R31: sequential logic.","quizQuestions":3,"anchor":"lesson-32.2"},{"id":"32.3","title":"Binary arithmetic, fixed point and overflow policies","outcome":"Choose representations that preserve the needed range and precision.","practical":"Implement wrapping and saturating addition plus a fixed-point multiply. Pass: boundary cases are exhaustive for a small width and an error report quantifies rounding behavior against a floating-point reference.","reading":"R15: arithmetic; R31: ALU construction; R35: integer arithmetic semantics as a software/hardware contract.","quizQuestions":3,"anchor":"lesson-32.3"},{"id":"32.4","title":"Clock domains, reset and metastability","outcome":"Recognize where synchronous assumptions stop applying.","practical":"Model a request/acknowledge crossing and explain its stability assumptions. Pass: the receiver never accepts a partially updated word in the protocol model, and the report states that simulation is not an analog metastability proof.","reading":"R15: synchronization and asynchronous inputs; deepen with R50 in later verification lessons.","quizQuestions":3,"anchor":"lesson-32.4"}]},{"number":33,"title":"SystemVerilog and verification-driven RTL design","prerequisites":"Module 32; Python and C++ foundations complete.","project":"Implement a parameterized synchronous FIFO in RTL with a Python or C++ reference model, automated tests, assertions and synthesis reports. Keep testbench behavior separate from synthesizable hardware.","lessons":[{"id":"33.1","title":"RTL semantics and synthesizable SystemVerilog","outcome":"Write a hardware description rather than a sequential software imitation.","practical":"Implement a counter and two-register swap using a simulator. Pass: tests explain old/new values at each edge, lint warnings are resolved or justified, and no unintended latches are inferred.","reading":"R32: language support, warnings and simulation; R33: synthesis concepts and supported constructs.","quizQuestions":3,"anchor":"lesson-33.1"},{"id":"33.2","title":"Testbenches, scoreboards and constrained stimulus","outcome":"Check behavior against an independent specification.","practical":"Create a FIFO testbench with empty, full, simultaneous read/write and reset cases. Pass: an intentionally corrupted RTL version is detected, and a seed plus trace reproduces the first mismatch.","reading":"R34: writing testbenches, triggers and simulator timing; R32: simulation and tracing.","quizQuestions":3,"anchor":"lesson-33.2"},{"id":"33.3","title":"Assertions, coverage and formal reasoning","outcome":"Distinguish observed tests from properties proven under assumptions.","practical":"Add occupancy, ordering and stalled-data assertions. Pass: bounded results state their depth, at least two meaningful cover goals are reached, and each environment assumption is justified.","reading":"R50: getting started, FIFO example, safety, cover and liveness; R34: assertion-oriented simulation checks.","quizQuestions":3,"anchor":"lesson-33.3"},{"id":"33.4","title":"Synthesis, constraints and FPGA resource mapping","outcome":"Connect verified behavior to a realizable implementation.","practical":"Synthesize the FIFO and compare two storage implementations or depths. Pass: record device/model, tool version, inferred memory, registers and timing constraints; reconcile any post-synthesis behavior differences.","reading":"R33: synthesis and memory mapping; R32: lint; selected FPGA tool documentation only after a target is chosen.","quizQuestions":3,"anchor":"lesson-33.4"}]},{"number":34,"title":"Designing a small processor","prerequisites":"Modules 16 and 32-33. Implement a documented subset, not an unqualified full-ISA claim.","project":"Create a simple processor model and RTL implementation for a clearly specified instruction subset. Run the same short programs on an instruction-level reference and the RTL, comparing architectural state at retirement.","lessons":[{"id":"34.1","title":"Instruction sets, datapaths and single-cycle execution","outcome":"Separate programmer-visible behavior from its implementation.","practical":"Implement arithmetic, load/store and one branch form in a reference model and datapath. Pass: hand-encoded programs produce the expected register and memory state and unsupported encodings have defined behavior.","reading":"R35: selected base integer instructions; R15: processor design; R31: computer architecture projects.","quizQuestions":3,"anchor":"lesson-34.1"},{"id":"34.2","title":"Pipelining, forwarding, stalls and branch recovery","outcome":"Preserve architectural behavior while overlapping instructions.","practical":"Pipeline the processor or model a pipeline with explicit valid bits. Pass: dependent arithmetic, load-use, branch-taken and back-to-back memory tests match the architectural reference.","reading":"R15: pipelined processors; R35: instruction semantics; R32: tracing and debugging.","quizQuestions":3,"anchor":"lesson-34.2"},{"id":"34.3","title":"Memory interfaces, caches and protection boundaries","outcome":"Design memory behavior as a protocol rather than an instantaneous array.","practical":"Add a variable-latency memory model and an optional direct-mapped cache. Pass: randomized stalls preserve program results, each accepted store occurs exactly as specified and cache tests include conflicting addresses.","reading":"R15: caches, memory and I/O; R35: memory access and selected privilege concepts as an extension.","quizQuestions":3,"anchor":"lesson-34.3"},{"id":"34.4","title":"Processor verification, toolchains and architectural evidence","outcome":"Demonstrate instruction correctness with reproducible programs and traces.","practical":"Run at least twenty directed programs and a reproducible randomized set against the reference. Pass: mismatch localization works, binary layout is documented and a supported compiled or assembled program runs end to end.","reading":"R35: exact chosen ISA revision; R32: simulation; R15: software/processor interface.","quizQuestions":3,"anchor":"lesson-34.4"}]},{"number":35,"title":"FPGA-based game subsystems and integration","prerequisites":"Modules 21, 31-34. Physical deployment is optional; simulated I/O satisfies the core project.","project":"Gate G: demonstrate a verified RTL game subsystem, such as a sprite compositor, controller interface or bounded vector unit. Include a software reference, interface specification, automated verification and synthesis evidence. A physical board is an extension, not a prerequisite.","lessons":[{"id":"35.1","title":"Memory-mapped I/O, timers, interrupts and DMA","outcome":"Explain how software controls asynchronous hardware.","practical":"Implement a simulated timer and memory-mapped control block. Pass: register side effects are specified, interrupts are acknowledged without losing new events and buffers remain owned until completion.","reading":"R15: I/O and interrupts; R35: ordering concepts for the chosen platform; R32: device testbench modeling.","quizQuestions":3,"anchor":"lesson-35.1"},{"id":"35.2","title":"Framebuffers, scanout and pixel pipelines","outcome":"Produce timed pixel data with correct storage and scheduling.","practical":"Create a simulated scanout counter and color-bar/sprite generator. Pass: exact active dimensions and frame boundaries are verified, captured images match the reference and buffer swapping occurs only at the declared boundary.","reading":"R15: digital-system timing; R32 and R34: timed testbenches; use the selected board vendor's documented video reference only for a physical extension.","quizQuestions":3,"anchor":"lesson-35.2"},{"id":"35.3","title":"A small accelerator and its software contract","outcome":"Measure whether specialized hardware improves a complete operation.","practical":"Build a streaming arithmetic or pixel block plus a software driver model. Pass: outputs match the reference over boundary cases, backpressure preserves order and end-to-end cost includes setup and transfer.","reading":"R33: synthesis and arithmetic mapping; R34: scoreboard verification; R15: parallelism and I/O.","quizQuestions":3,"anchor":"lesson-35.3"},{"id":"35.4","title":"Integrated digital-design review and optional board bring-up","outcome":"Close the loop between specification, verification and implementation.","practical":"Complete Gate G with an integration test, synthesis report and short demonstration. Pass: another person reruns the simulation, all timing assumptions are listed and any physical measurements are distinguished from modeled estimates.","reading":"R32-R34: repeatable simulation and synthesis; R15: system integration; handbook safety review for physical extensions.","quizQuestions":3,"anchor":"lesson-35.4"}]}],"lessonCount":20},{"number":8,"title":"Gaming Platforms and Hardware/Software Co-design","level":"Upper undergraduate CE / capstone","purpose":"Study boards, memory, GPU architecture, performance, input/display pipelines and integrated design.","hours":{"minimum":350,"maximum":560},"checkpoint":{"id":"H","title":"undergraduate hardware/software co-design capstone"},"reader":"Game_Engineering_Package_09/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_09/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_09/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_09/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_09/LAB_WORKBOOK.pdf"},{"label":"Checkpoint H brief","path":"Game_Engineering_Package_09/CAPSTONE_SPEC.pdf"},{"label":"Platform reference","path":"Game_Engineering_Package_09/PLATFORM_REFERENCE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_09/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":36,"title":"Embedded platforms, drivers and board design","prerequisites":"Modules 17-18 and 31-35. Physical work remains optional and supervised.","project":"Design a simulated controller or peripheral with firmware, a host interface and a schematic-level review. A physical board extension begins only after the electrical, layout and bring-up plans receive qualified review.","lessons":[{"id":"36.1","title":"Serial interfaces and peripheral contracts","outcome":"Choose a communication interface using timing and electrical constraints.","practical":"Build a simulated peripheral transaction decoder and driver for one interface. Pass: incorrect framing or mode is detected, timeouts are bounded and a complete interface-contract table is provided.","reading":"R53: device drivers, UART, SPI and I2C APIs; R51: bus-level driver documentation. For hardware, add the exact peripheral datasheet.","quizQuestions":3,"anchor":"lesson-36-1"},{"id":"36.2","title":"Firmware, RTOS scheduling and driver lifecycle","outcome":"Bound embedded work and make device state transitions explicit.","practical":"Use a supported RTOS simulator or a deterministic scheduler model to implement input, processing and logging tasks. Pass: deadlines are evaluated under injected load and removal/cancellation leaves no live invalid requests.","reading":"R53: kernel scheduling, synchronization and device model; R51: driver lifecycle and power management.","quizQuestions":3,"anchor":"lesson-36-2"},{"id":"36.3","title":"Schematics, PCB layout, power integrity and signal integrity","outcome":"Translate a circuit into a manufacturable layout without ignoring physics.","practical":"Create a low-speed peripheral schematic and unrouted or simple two-layer layout in KiCad. Pass: footprints are checked against datasheets, ERC/DRC findings are resolved or justified and a reviewer inspects power and return paths before fabrication.","reading":"R36: schematic editor, PCB editor, ERC and DRC; R30: nonideal circuit behavior; R49: interconnect and packaging extension.","quizQuestions":3,"anchor":"lesson-36-3"},{"id":"36.4","title":"Bring-up, instrumentation and fault isolation","outcome":"Turn an unresponsive device into a sequence of testable hypotheses.","practical":"Write and rehearse a bring-up procedure against a simulated device with injected clock, reset and protocol faults. Pass: each fault has a safe diagnostic branch and the procedure includes explicit stop conditions.","reading":"R53: board support and debugging; R36: fabrication outputs and design review; selected instrument manuals for any physical extension.","quizQuestions":3,"anchor":"lesson-36-4"}]},{"number":37,"title":"GPU microarchitecture and memory systems","prerequisites":"Modules 16, 22, 32 and 34.","project":"Create a GPU architecture workbook connecting shader behavior to execution groups, registers, memory transactions and fixed-function resources. Measure one accessible GPU or clearly label a simulator-only study.","lessons":[{"id":"37.1","title":"SIMT execution, divergence, occupancy and latency hiding","outcome":"Explain why many threads do not guarantee useful parallel work.","practical":"Compare coherent and divergent workloads, varying register pressure or group size where supported. Pass: outputs agree, device group assumptions are recorded and the report does not equate occupancy with performance.","reading":"R37: programming model, execution and hardware implementation; R48: vector and multithreaded architecture foundations.","quizQuestions":3,"anchor":"lesson-37-1"},{"id":"37.2","title":"Coalescing, local storage, caches and shared-memory banks","outcome":"Match data layout to the memory transactions actually performed.","practical":"Benchmark contiguous, strided and tiled access with identical useful work. Pass: count useful bytes, state the relevant memory level and include any layout-conversion cost in the application comparison.","reading":"R37: device memory access, shared memory and performance considerations; R43: operational intensity.","quizQuestions":3,"anchor":"lesson-37-2"},{"id":"37.3","title":"Raster, texture, matrix and ray-tracing units","outcome":"Understand fixed-function acceleration as specialized tradeoffs.","practical":"Analyze one texture-heavy, arithmetic-heavy or ray-query workload. Pass: identify the likely resource limits using measurements or a documented model and state supported precision and feature assumptions.","reading":"R37: architecture and specialized operations; R21: graphics/compute capabilities; R23: ray intersection and acceleration reference.","quizQuestions":3,"anchor":"lesson-37-3"},{"id":"37.4","title":"CPU-GPU sharing, discrete memory and synchronization","outcome":"Treat shared addressability separately from ownership and cost.","practical":"Compare an upload/compute/readback path with an available shared-memory path, or model both with stated assumptions. Pass: correct ownership, separate phase timings and no claim that unified means zero-cost.","reading":"R37: memory management and synchronization; R21, R24 or R25: the selected platform's resource-sharing contract.","quizQuestions":3,"anchor":"lesson-37-4"}]},{"number":38,"title":"Quantitative performance engineering","prerequisites":"Modules 09, 16, 18, 30 and 37.","project":"Produce a performance investigation with a hypothesis, controlled workload, raw measurements, uncertainty, a bottleneck model and a verified optimization. A negative result is acceptable when the evidence is rigorous.","lessons":[{"id":"38.1","title":"Amdahl, roofline and bottleneck models","outcome":"Use upper bounds to reject implausible optimization claims.","practical":"Build a roofline worksheet for one kernel and an Amdahl estimate for one frame optimization. Pass: units cancel correctly, modeled ceilings use the declared memory level and observed deviations are explained as hypotheses.","reading":"R43: original Roofline model; R48: quantitative architecture; revisit Module 18 parallel limits.","quizQuestions":3,"anchor":"lesson-38-1"},{"id":"38.2","title":"Profilers, counters and trustworthy benchmark design","outcome":"Distinguish observation from an explanation that still needs testing.","practical":"Create a benchmark harness with warmup, repeated runs, output validation and metadata. Pass: an intentional no-op or wrong-result variant is rejected and all included/excluded samples are documented.","reading":"R26: profiling; R37: performance analysis; R09: inference and uncertainty.","quizQuestions":3,"anchor":"lesson-38-2"},{"id":"38.3","title":"SIMD, cache blocking, NUMA and job scheduling","outcome":"Optimize locality and parallelism together.","practical":"Optimize a particle or transform workload using one locality change and one scheduling change. Pass: test tail sizes, report numerical differences, and measure small as well as large workloads to expose overhead.","reading":"R37: parallel memory patterns; R48: multiprocessors and memory systems; R11: safe C++ and concurrency.","quizQuestions":3,"anchor":"lesson-38-3"},{"id":"38.4","title":"Energy, thermal behavior and sustained performance","outcome":"Evaluate useful work over time rather than only a short peak.","practical":"Run a sustained workload within normal device limits or analyze a synthetic power trace. Pass: distinguish watts from joules, report the measurement boundary and compare early versus sustained performance.","reading":"R48: quantitative architecture; R51: device power management; R37: GPU execution and performance context.","quizQuestions":3,"anchor":"lesson-38-4"}]},{"number":39,"title":"Gaming-platform constraints and interactive latency","prerequisites":"Modules 22, 27, 29 and 36-38.","project":"Create a platform capability and latency report for the engine. Implement one non-desktop constraint in simulation or on an available device: touch input, suspend/resume, restricted memory, variable presentation or XR timing.","lessons":[{"id":"39.1","title":"Input-to-display latency and frame pacing","outcome":"Account for the whole interaction path rather than only frame rate.","practical":"Instrument input receipt, simulation consumption, render submission and presentation-related timestamps. Pass: explain which stages are actually measured and which remain estimated, and show a frame-pacing distribution.","reading":"R22: input and event timing; R24 or R25: presentation; R52: frame timing as an advanced comparison.","quizQuestions":3,"anchor":"lesson-39-1"},{"id":"39.2","title":"Mobile and handheld systems: memory, power and lifecycle","outcome":"Design for suspension, limited budgets and sustained use.","practical":"Add suspend/resume simulation and a constrained memory mode. Pass: progress survives the documented lifecycle, resources are restored safely and quality changes do not alter authoritative simulation rules.","reading":"R25: platform graphics resources; R22: application lifecycle events; R29: text and input usability; R51: power-management concepts.","quizQuestions":3,"anchor":"lesson-39-2"},{"id":"39.3","title":"XR spaces, stereo views, pose timing and comfort constraints","outcome":"Render from runtime-provided timing and coordinate contracts.","practical":"Implement two simulated camera views and a pose-time log, or a minimal OpenXR scene on available supported hardware. Pass: spaces and units are explicit, frame timing follows the runtime and loss of tracking has defined behavior.","reading":"R52: spaces, view configuration, frame loop and timing; R29: interaction and accessibility review.","quizQuestions":3,"anchor":"lesson-39-3"},{"id":"39.4","title":"Portability, platform services and console-development boundaries","outcome":"Build transferable systems without assuming proprietary access.","practical":"Write a platform interface and capability matrix, then implement a second backend or strict mock. Pass: assumptions about paths, input and lifecycle are exposed, and proprietary requirements are marked unavailable until authorized.","reading":"R22, R24 and R25: platform interfaces; R29: cross-device usability; official authorized platform documentation only for restricted targets.","quizQuestions":3,"anchor":"lesson-39-4"}]},{"number":40,"title":"Hardware/software co-design capstone","prerequisites":"Gates F and G; Modules 36-39.","project":"Gate H: choose one game workload and compare a software baseline with a specialized hardware or architecture alternative. Deliver a reference implementation, model or RTL, software interface, verification evidence and an end-to-end tradeoff report.","lessons":[{"id":"40.1","title":"Workload characterization and measurable requirements","outcome":"Derive hardware goals from a real software operation.","practical":"Select a workload from the engine and write a requirement sheet plus baseline measurements. Pass: each target has units and a test, and the maximum plausible application benefit is estimated.","reading":"R43: bottleneck modeling; R48: quantitative design; R49: project methodology.","quizQuestions":3,"anchor":"lesson-40-1"},{"id":"40.2","title":"Architecture alternatives, arithmetic precision and dataflow","outcome":"Explore several designs before committing to one.","practical":"Model three variants, such as scalar, pipelined and multi-lane. Pass: resource and bandwidth estimates are explicit, fixed-point error meets a chosen application tolerance and rejected variants have documented reasons.","reading":"R49: architecture and RTL modeling; R43: bandwidth limits; R33: resource inference.","quizQuestions":3,"anchor":"lesson-40-2"},{"id":"40.3","title":"Interface design, virtualization and end-to-end evaluation","outcome":"Include the host software in the hardware result.","practical":"Implement a host driver model with invalid-descriptor, timeout and reset tests. Pass: buffer bounds are enforced, ownership survives failure and results include both kernel and end-to-end timing.","reading":"R51: DMA and device interfaces; R49: system integration; R38: modeled systems when hardware is unavailable.","quizQuestions":3,"anchor":"lesson-40-3"},{"id":"40.4","title":"Design review, evidence tiers and undergraduate CE completion","outcome":"Defend a co-design decision with limitations and reproducible artifacts.","practical":"Complete Gate H and a design-review presentation. Pass: every major claim traces to an artifact, the baseline is reproduced and a limitations section clearly separates educational estimates from production claims.","reading":"R49: design-project reporting; R48: architectural tradeoffs; revisit the evidence and project rubrics in the handbook.","quizQuestions":3,"anchor":"lesson-40-4"}]}],"lessonCount":20},{"number":9,"title":"Graduate Game-Engine and Graphics Engineering","level":"Master's-level specialization","purpose":"Derive algorithms, reproduce research, optimize parallel systems and defend measured engineering choices.","hours":{"minimum":550,"maximum":850},"checkpoint":{"id":"I","title":"graduate reproduction and extension"},"reader":"Game_Engineering_Package_10/COURSE.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_10/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_10/START_NEXT.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_10/STUDENT_HANDBOOK.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_10/LAB_WORKBOOK.pdf"},{"label":"Checkpoint I brief","path":"Game_Engineering_Package_10/CAPSTONE_SPEC.pdf"},{"label":"Reference guide","path":"Game_Engineering_Package_10/REFERENCE_GUIDE.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_10/ANSWER_KEY.pdf","answers":true}],"modules":[{"number":41,"title":"Graduate numerical methods and research practice","prerequisites":"Gates B, F and H; rigorous linear algebra, calculus, probability and systems competence.","project":"Produce a graduate numerical notebook with derivations, reference implementations, conditioning experiments and a preregistered evaluation plan. Complete substantial assigned problem sets; the short lesson quizzes are only formative checks.","lessons":[{"id":"41.1","title":"Reading research as claims, assumptions and evidence","outcome":"Extract an implementable argument rather than only a paper summary.","practical":"Analyze one paper associated with R23, R44 or R55. Pass: a two-page claim map, a reconstructed central algorithm, at least three assumptions and a feasible reproduction target are reviewed by another reader.","reading":"R23: Further Reading sections for a chosen rendering topic; R44 or R55: one named original paper; handbook research-reading template.","quizQuestions":3,"anchor":"lesson-41-1"},{"id":"41.2","title":"Conditioning, sparse systems and iterative solvers","outcome":"Choose a solver from mathematical properties and error requirements.","practical":"Implement a sparse matrix-vector product and conjugate gradient for a verified SPD system. Pass: derive the relevant assumptions, compare residual and forward error, and evaluate a simple preconditioner over several conditioning levels.","reading":"R54: linear systems, positive definiteness and numerical methods; R07: orthogonality and eigenvalues; R42: numerical optimization background.","quizQuestions":3,"anchor":"lesson-41-2"},{"id":"41.3","title":"Constrained optimization, derivatives and optimality conditions","outcome":"Derive and verify an optimization method for an engineering objective.","practical":"Derive the example, then solve a constrained fitting or IK problem with a numerical method. Pass: derivative checks, feasibility residual, convergence criteria and at least one failure or sensitivity case are reported.","reading":"R42: convexity, duality, optimality and numerical methods; R41: gradients and constrained differentials.","quizQuestions":3,"anchor":"lesson-41-3"},{"id":"41.4","title":"Experimental design, uncertainty and reproducible graduate work","outcome":"Make a performance or quality claim that survives independent scrutiny.","practical":"Preregister a small experiment with baseline, primary metric, trial unit and exclusion policy. Pass: raw data and analysis scripts reproduce the tables, and an ablation isolates at least one proposed mechanism.","reading":"R09: statistical inference; R42: experimental examples; handbook benchmark and research templates.","quizQuestions":3,"anchor":"lesson-41-4"}]},{"number":42,"title":"Advanced parallel and GPU algorithms","prerequisites":"Modules 18, 37-38 and 41.","project":"Implement a reusable GPU reduction, scan or compaction primitive and integrate it into an engine workload. Compare a simple reference, a competent library baseline when available and your implementation at equal correctness requirements.","lessons":[{"id":"42.1","title":"Parallel reductions, scans and work-span analysis","outcome":"Prove the structure of a parallel primitive before tuning it.","practical":"Implement reduction and either scan or compaction. Pass: derive work/span bounds, test sizes 0, 1 and non-powers of two, and report the numerical/reproducibility contract.","reading":"R37: cooperative execution and synchronization; R48: parallel architectures; derive algorithm bounds using Module 14 methods.","quizQuestions":3,"anchor":"lesson-42-1"},{"id":"42.2","title":"Tiling, data reuse and asynchronous pipelines","outcome":"Overlap movement and computation without creating races.","practical":"Implement a tiled matrix multiply or image filter, then one overlap variant where supported. Pass: adversarial dimensions match the reference, synchronization is checked and the end-to-end comparison includes staging overhead.","reading":"R37: shared memory, synchronization and asynchronous operations where supported; R43: operational intensity.","quizQuestions":3,"anchor":"lesson-42-2"},{"id":"42.3","title":"Irregular workloads, wavefront scheduling and load balance","outcome":"Design around variable work rather than assuming identical threads.","practical":"Implement an irregular workload using static assignment and a queue or compaction alternative. Pass: prove or test termination, handle queue capacity safely and measure tail behavior as well as mean throughput.","reading":"R37: execution, atomics and synchronization; R48: multithreaded scheduling; R23: wavefront rendering as an application.","quizQuestions":3,"anchor":"lesson-42-3"},{"id":"42.4","title":"Portable performance and integration-quality evaluation","outcome":"Separate algorithmic benefit from one device-specific tuning win.","practical":"Integrate the selected primitive into the engine and evaluate at least two workload regimes. Pass: application impact is measured, unsupported features fall back safely and any untested device claims are explicitly excluded.","reading":"R37 and R21: capability contracts; R43: performance models; Module 41 experimental protocol.","quizQuestions":3,"anchor":"lesson-42-4"}]},{"number":43,"title":"Advanced rendering and reconstruction","prerequisites":"Modules 09-10, 21-23 and 41-42.","project":"Reproduce a bounded rendering result and add one justified extension. Derive the estimator or reconstruction objective, compare equal-quality cost, include temporal failure cases and preserve source scenes and evaluation scripts.","lessons":[{"id":"43.1","title":"Monte Carlo light transport and multiple importance sampling","outcome":"Derive estimators with correct densities and measures.","practical":"Implement a path tracer with explicit light sampling and MIS. Pass: derive the estimator, verify a simple known integral, compare variance at equal cost and test emission and grazing-angle edge cases.","reading":"R23: Monte Carlo Integration, Light Transport and sampling strategies. Work the associated mathematical exercises, not only the implementation.","quizQuestions":3,"anchor":"lesson-43-1"},{"id":"43.2","title":"Real-time ray tracing, dynamic acceleration and hybrid pipelines","outcome":"Budget traversal, building and shading as one system.","practical":"Add one ray-traced effect to the engine or build a software hybrid prototype. Pass: dynamic-scene tests include total update cost, missing-information fallbacks and resource synchronization evidence.","reading":"R23: intersection acceleration and light transport; R21, R24 or R25: supported ray-tracing interfaces for an optional hardware route.","quizQuestions":3,"anchor":"lesson-43-2"},{"id":"43.3","title":"Spatiotemporal reuse, reservoirs and denoising","outcome":"Evaluate variance reduction together with bias, history validity and motion.","practical":"Reproduce a small weighted-reservoir example or temporal denoiser, then evaluate on motion and disocclusion sequences. Pass: the selection/weight rule is derived, bias limitations are stated and results include sequence-level failure cases.","reading":"R44: original ReSTIR paper and its estimator assumptions; R23: sampling theory; read only the selected bounded method before expanding scope.","quizQuestions":3,"anchor":"lesson-43-3"},{"id":"43.4","title":"Differentiable and neural rendering under engineering constraints","outcome":"Test learned or gradient-based methods against explicit baselines.","practical":"Implement a small inverse-rendering optimization or learned reconstruction experiment. Pass: gradient or generalization checks, a non-learned baseline, compute/memory accounting and a distribution-shift failure analysis are included.","reading":"R47: automatic differentiation, optimization and generalization; R23: light transport and sampling foundations; select one original method with Module 41's paper-review protocol.","quizQuestions":3,"anchor":"lesson-43-4"}]},{"number":44,"title":"Advanced engine systems and simulation research","prerequisites":"Gates F-H; Modules 41-43.","project":"Conduct an engine-system experiment with a formal model or numerical argument, a reference implementation and stress-tested integration. Choose one main depth area: world streaming, simulation, distributed state or reliability.","lessons":[{"id":"44.1","title":"Large-world scheduling, streaming and critical-path control","outcome":"Design a bounded system under changing content and workload.","practical":"Implement a bounded world-streaming scheduler or large-coordinate experiment. Pass: teleport and memory-pressure tests preserve correctness, peak resources are measured and the critical path is explained with a trace.","reading":"R26: world, task and streaming systems for comparison; R20: engine architecture; R54: numerical conditioning where coordinate precision is studied.","quizQuestions":3,"anchor":"lesson-44-1"},{"id":"44.2","title":"Deformable simulation, variational models and solver tradeoffs","outcome":"Derive a physical or constraint model before comparing visual results.","practical":"Implement a small cloth, elastic bar or compliant-constraint model and compare two integration/solver choices. Pass: derive the core equations, check gradients, quantify constraint or energy error and reproduce one bounded result from the assigned research.","reading":"R54: equilibrium, variational and differential-equation methods; R55: 2016 XPBD and related position-based simulation course notes.","quizQuestions":3,"anchor":"lesson-44-2"},{"id":"44.3","title":"Distributed game state, consistency and overload behavior","outcome":"Specify which guarantees survive network delay and partial failure.","practical":"Model a two-partition entity handoff with injected failure. Pass: a stated safety invariant holds, recovery assumptions are explicit and overload is bounded without unbounded retry amplification.","reading":"R17-R18: transport and transactions; R20: game-state architecture; use Module 41's claim and experiment discipline for the distributed model.","quizQuestions":3,"anchor":"lesson-44-3"},{"id":"44.4","title":"Formal specifications, replay and reliability-oriented engine design","outcome":"Use precise invariants to reduce the space of subtle failures.","practical":"Model a small engine lifecycle or queue protocol and connect it to implementation tests. Pass: at least one safety and one conditional liveness property are defined, a deliberate violation is found and abstraction limits are documented.","reading":"R50: safety, liveness and assumptions as a formal-methods reference; R11 and Module 18: ownership/concurrency contracts; R26: system comparison.","quizQuestions":3,"anchor":"lesson-44-4"}]},{"number":45,"title":"Compilers, shader languages and engine specialization","prerequisites":"Modules 15-16, 18, 37 and 41-42.","project":"Gate I: deliver a research-quality reproduction and extension in rendering, simulation, GPU algorithms or compilation. This module also requires a small compiler optimization with semantic tests, generated-code inspection and end-to-end measurements.","lessons":[{"id":"45.1","title":"Intermediate representations, SSA and dataflow analysis","outcome":"Represent program meaning so transformations can be justified.","practical":"Extend the tiny compiler with a control-flow IR and one dataflow analysis. Pass: derive transfer functions and a fixed-point stopping condition, test loops and merges, and verify transformed programs against an interpreter.","reading":"R14: LLVM frontend, control flow and optimization tutorials; R48: compiler/architecture interaction.","quizQuestions":3,"anchor":"lesson-45-1"},{"id":"45.2","title":"Alias analysis, vectorization and legal optimization","outcome":"Separate transformations that are fast from transformations that preserve meaning.","practical":"Implement or study a loop transformation with an explicit legality check. Pass: overlapping-memory and boundary cases are tested, compiler flags are recorded and speed claims exclude transformations that violate the required numerical contract.","reading":"R14: optimization and code generation; R11: aliasing, lifetime and arithmetic guidance; R37: vector/parallel execution consequences.","quizQuestions":3,"anchor":"lesson-45-2"},{"id":"45.3","title":"Domain-specific languages, specialization and safe JIT execution","outcome":"Trade generality for predictable game-engine computation.","practical":"Build a typed expression or material DSL with constant folding and a bounded interpreter or JIT route. Pass: invalid graphs fail safely, variant counts are measured and compiled outputs match the reference.","reading":"R14: language implementation and JIT; R26: material and scripting concepts for comparison; Module 20: trust boundaries.","quizQuestions":3,"anchor":"lesson-45-3"},{"id":"45.4","title":"Compiler/hardware co-design and graduate artifact review","outcome":"Connect a transformation to architecture and application evidence.","practical":"Complete Gate I and defend one compiler transformation's legality. Pass: an independent reader reruns the central experiment, the claimed extension is precisely identified and raw evidence supports the conclusions.","reading":"R14 and R48: compilation and architecture; R49: co-design methodology; Module 41: research evaluation protocol.","quizQuestions":3,"anchor":"lesson-45-4"}]}],"lessonCount":20},{"number":10,"title":"Graduate Gaming Hardware and Research Thesis","level":"Master's-level specialization / thesis","purpose":"Evaluate advanced architectures, physical design and verification, then complete and defend a research artifact.","hours":{"minimum":810,"maximum":1380},"checkpoint":{"id":"J","title":"thesis, defense and handoff"},"reader":"Game_Engineering_Package_11/browser/index.html","resources":[{"label":"Package README","path":"Game_Engineering_Package_11/README.md"},{"label":"Start guide","path":"Game_Engineering_Package_11/pdf/START_HERE.pdf"},{"label":"Student handbook","path":"Game_Engineering_Package_11/pdf/Volume_10_Student_Handbook.pdf"},{"label":"Lab workbook","path":"Game_Engineering_Package_11/pdf/Volume_10_Lab_Workbook.pdf"},{"label":"Checkpoint J brief","path":"Game_Engineering_Package_11/pdf/Gate_J_Thesis_Defense_and_Handoff.pdf"},{"label":"Math and reference guide","path":"Game_Engineering_Package_11/pdf/Volume_10_Math_and_Reference.pdf"},{"label":"Answer key","path":"Game_Engineering_Package_11/pdf/Volume_10_Answer_Key.pdf","answers":true}],"modules":[{"number":46,"title":"Advanced computer architecture for gaming workloads","prerequisites":"Modules 34, 37-40 and 41-42.","project":"Perform an architecture study using a pinned simulator or a carefully bounded analytical model. Compare at least three configurations on representative and adverse game-related workloads, and validate the model against a known reference where possible.","lessons":[{"id":"46.1","title":"Cache coherence, memory consistency and synchronization","outcome":"Separate agreement about a location from ordering across locations.","practical":"Model a small coherence protocol and evaluate message-passing litmus tests under stated language and hardware models. Pass: ownership invariants hold, transient races are considered and coherence is not confused with data-race freedom.","reading":"R48: multiprocessors, coherence and consistency; R35: selected memory-ordering specification; R11: language-level concurrency.","quizQuestions":3,"anchor":"lesson-46-1"},{"id":"46.2","title":"Out-of-order execution, speculation and precise state","outcome":"Increase instruction overlap without changing architectural outcomes.","practical":"Use a simulator or detailed scheduling model to compare in-order and out-of-order execution on independent and dependent instruction streams. Pass: architectural results agree and bottleneck explanations include true dependencies and resource limits.","reading":"R48: superscalar, out-of-order, prediction and exception handling; R38: CPU models and configuration.","quizQuestions":3,"anchor":"lesson-46-2"},{"id":"46.3","title":"Architecture simulation, traces and model validation","outcome":"Use simulation as evidence with a stated fidelity boundary.","practical":"Run a cache, scheduling or accelerator study with at least one validation case and a sensitivity sweep. Pass: raw configurations reproduce results, modeled versus measured quantities are labeled and conclusions do not exceed the tested fidelity.","reading":"R38: simulation models, statistics and configuration; R48: architecture evaluation; R43: analytical bounds.","quizQuestions":3,"anchor":"lesson-46-3"},{"id":"46.4","title":"Memory systems, chiplets and multi-objective design","outcome":"Choose an architecture across performance, power, cost and complexity.","practical":"Construct a Pareto comparison of at least three architecture configurations. Pass: objectives and assumptions are explicit, dominated designs are identified correctly and a recommendation changes appropriately when a hard constraint changes.","reading":"R48: memory and quantitative design; R49: packaging and system tradeoffs; R38: architecture alternatives.","quizQuestions":3,"anchor":"lesson-46-4"}]},{"number":47,"title":"VLSI, timing and physical implementation","prerequisites":"Modules 31-34, 40 and 46. Use educational libraries and licensed or open tools only.","project":"Carry a verified small RTL block through an educational synthesis and physical-design flow. Report constraints, timing, area and power-estimation assumptions. The result is a learning artifact, not fabrication-ready commercial signoff.","lessons":[{"id":"47.1","title":"CMOS logic, transistor sizing and delay models","outcome":"Connect gate-level choices to electrical load and timing.","practical":"Analyze and simulate an inverter chain or compare library-cell drive strengths under several loads. Pass: assumptions are stated, input loading is included and model predictions are compared with available characterized or simulated results.","reading":"R49: CMOS devices, combinational circuits and delay; R30: MOS circuit foundations.","quizQuestions":3,"anchor":"lesson-47-1"},{"id":"47.2","title":"Static timing analysis, clocks and timing exceptions","outcome":"Check every required path under the correct timing contract.","practical":"Constrain a small sequential block and inspect worst setup and hold paths. Pass: no unexplained unconstrained endpoints, every exception is justified and a deliberately tightened clock produces an understood violation.","reading":"R39: timing analysis and flow constraints; R49: sequential timing and clocking.","quizQuestions":3,"anchor":"lesson-47-2"},{"id":"47.3","title":"Synthesis, placement, clock trees, routing and physical checks","outcome":"Understand how a logical netlist becomes a physical layout.","practical":"Run a small block through an educational OpenROAD-compatible flow or inspect a provided open example. Pass: capture stage reports, identify a routing/timing change and state which physical checks were and were not performed.","reading":"R39: flow stages, placement, clock tree and routing; R49: physical-design methodology and EDA.","quizQuestions":3,"anchor":"lesson-47-3"},{"id":"47.4","title":"Power, area, process corners and design-space closure","outcome":"Report PPA with enough assumptions to make comparison meaningful.","practical":"Compare two verified RTL implementations using identical flow assumptions. Pass: report area, worst timing and activity-based power estimates where supported, with uncertainty and no unsupported commercial-silicon claim.","reading":"R49: power, timing and implementation tradeoffs; R39: reports and analysis; R30: energy and electrical models.","quizQuestions":3,"anchor":"lesson-47-4"}]},{"number":48,"title":"Verification, reliability and hardware trust boundaries","prerequisites":"Modules 33-35, 46-47.","project":"Create a verification dossier for the hardware capstone: requirements-to-tests traceability, assertions, coverage, clock/reset review, fault injection and a clearly bounded assurance claim.","lessons":[{"id":"48.1","title":"Formal properties, abstraction and assume-guarantee reasoning","outcome":"Prove useful properties without hiding failures in assumptions.","practical":"Prove a queue, arbiter or transaction property and inject a violation. Pass: assumptions are reviewed independently, contention is covered and bounded, proven, failed and unknown results are reported separately.","reading":"R50: safety, liveness, induction, cover and assumptions; R49: verification methodology.","quizQuestions":3,"anchor":"lesson-48-1"},{"id":"48.2","title":"Clock/reset crossings and asynchronous FIFO verification","outcome":"Check digital protocol correctness while acknowledging analog risk.","practical":"Model an asynchronous FIFO or event handshake with independent clocks and reset sequences. Pass: no loss/duplication under the stated protocol, full/empty behavior is checked and physical synchronizer assumptions are listed separately.","reading":"R50: multiclock modeling and verification; R49: sequential circuits and synchronization; revisit Module 32 timing boundaries.","quizQuestions":3,"anchor":"lesson-48-2"},{"id":"48.3","title":"Fault models, ECC, testability and recovery","outcome":"Design for detectable failures rather than assuming perfect hardware.","practical":"Implement a parity and a small single-error-correcting code model, then inject faults. Pass: enumerate the supported correction/detection claims, test multi-bit counterexamples and define a recovery response.","reading":"R49: testing, DFT and reliability context; R51: error detection/correction reporting concepts; R06: coding and combinatorial reasoning extension.","quizQuestions":3,"anchor":"lesson-48-3"},{"id":"48.4","title":"Hardware security, thermal limits and assurance review","outcome":"Include isolation and failure containment in the design contract.","practical":"Write a threat-and-failure review for the accelerator and test malformed descriptors, denied access and reset under load in simulation. Pass: isolation limits, protection assumptions and unresolved risks are explicit; no unauthorized target testing occurs.","reading":"R51: device access, DMA and isolation; R49: implementation and verification; R50: enforceable protocol properties.","quizQuestions":3,"anchor":"lesson-48-4"}]},{"number":49,"title":"Master's thesis: proposal, implementation and evaluation","prerequisites":"Gate I and relevant advanced-track modules; independent technical mentorship strongly recommended.","project":"Prepare and execute a thesis-scale project in one primary specialization. Budget 400-800 focused hours as a planning range, with scope adjusted through review. The deliverable is a defensible contribution and reproducible artifact, not a promise of publication.","lessons":[{"id":"49.1","title":"Question selection, literature map and thesis scope","outcome":"Turn a broad interest into a falsifiable, feasible research question.","practical":"Write a 3-5 page proposal with a research question, 8-15 relevant sources, baseline plan, constraints and exclusions. Pass: a reviewer can explain what observation would weaken or refute the main hypothesis.","reading":"Use Module 41's paper method and the chosen track's original papers; R44, R48, R49 or R55 are starting anchors, not a substitute for the literature search.","quizQuestions":3,"anchor":"lesson-49-1"},{"id":"49.2","title":"Proposal review, baselines and risk-reduction milestones","outcome":"Make failure cheap before the expensive implementation phase.","practical":"Deliver a running baseline, risk register and milestone plan. Pass: the primary metric can be measured, a small feasibility experiment exists and each major risk has a mitigation or explicit acceptance decision.","reading":"R49: project milestone and reporting structure; Module 41: experimental design; chosen method's primary documentation.","quizQuestions":3,"anchor":"lesson-49-2"},{"id":"49.3","title":"Implementation, ablations and controlled evaluation","outcome":"Execute the study without changing the question to fit a favorable result.","practical":"Run the approved evaluation with baselines, at least one ablation and one sensitivity study. Pass: scripts regenerate results, failed cases remain visible and claims use the preregistered primary metric or clearly disclose deviations.","reading":"R09 and Module 41: uncertainty; chosen track's original methods and implementation references; handbook experiment manifest.","quizQuestions":3,"anchor":"lesson-49-3"},{"id":"49.4","title":"Thesis writing, reproducibility and contribution boundaries","outcome":"Write a technical argument another engineer can audit.","practical":"Produce a thesis-style report, typically 30-60 pages plus appendices as a planning guide, and a complete artifact package. Pass: a reviewer traces five major claims to evidence and reproduces the central table or experiment.","reading":"R49: final project reports; chosen original papers for reporting comparisons; handbook thesis outline and evidence checklist.","quizQuestions":3,"anchor":"lesson-49-4"}]},{"number":50,"title":"Thesis defense, professional practice and continued development","prerequisites":"Module 49 and all prerequisites for the selected specialization.","project":"Gate J: defend the thesis, pass an independent artifact reproduction, complete a maintainable handoff and publish an honest portfolio where rights permit. This completes the self-study program, not an accredited degree.","lessons":[{"id":"50.1","title":"Oral defense and independent artifact reproduction","outcome":"Show that the learner owns the reasoning and implementation.","practical":"Hold a 30-45 minute technical defense with a qualified reviewer or peer panel and a separate artifact run. Pass: the central result is reproduced, major questions receive evidence-based answers and required revisions are completed.","reading":"R49: design-project evaluation as a reference; handbook defense questions and rubric.","quizQuestions":3,"anchor":"lesson-50-1"},{"id":"50.2","title":"Mature-codebase integration, review and maintainable contributions","outcome":"Transfer a prototype into an engineering environment with other owners.","practical":"Integrate one tested improvement into a mature open codebase or a maintained local fork. Pass: a focused patch, regression test, design rationale and reviewer response are included, whether or not an upstream project accepts it.","reading":"R05: distributed workflows and contributing; R11: interfaces and maintenance; R26: mature-engine comparison where authorized.","quizQuestions":3,"anchor":"lesson-50-2"},{"id":"50.3","title":"Portfolio, technical interviews and role-specific evidence","outcome":"Present concrete engineering competence without inflated claims.","practical":"Prepare three portfolio case studies and complete one systems, one algorithm and one specialization mock interview. Pass: every claimed result is supported by an artifact and assistance or third-party contributions are clearly attributed.","reading":"R01-R02: breadth review; R11: engineering explanation and contracts; handbook role map and portfolio template.","quizQuestions":3,"anchor":"lesson-50-3"},{"id":"50.4","title":"Long-term learning, maintenance and final handoff","outcome":"Keep the knowledge and artifacts useful after the course ends.","practical":"Complete Gate J: archive the thesis artifact, produce a maintainer handoff and write a 90-day learning plan with one primary gap and one real contribution goal. Pass: another person can locate, build and understand the project without the author's machine.","reading":"R05: maintenance workflows; R01-R02: periodic breadth review; current official documentation for the selected tools when an update is undertaken.","quizQuestions":3,"anchor":"lesson-50-4"}]}],"lessonCount":20}]};
